INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('b5952302-4b3d-50f5-9140-c6cd356c84b1','1','gyoogle','doc:gyoogle:b2a0290b13f76a8981d0f886455f15c88df7883ad66c33041f6ce3d4e10dab94','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:714f92aa15b5bd34466b0024eda32e76f4d3b8dc114060a2914acd545b6e9215','csas-gyoogle-bank-v1','최대공약수 & 최소공배수','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Algorithm/%EC%B5%9C%EB%8C%80%EA%B3%B5%EC%95%BD%EC%88%98%20%26%20%EC%B5%9C%EC%86%8C%EA%B3%B5%EB%B0%B0%EC%88%98.md','Algorithm/최대공약수 & 최소공배수.md#유클리드 호제법을 활용하자!','##### 유클리드 호제법을 활용하자!

> 주어진 값에서 큰 값 % 작은 값으로 나머지를 구한다.
>
> 나머지가 0이 아니면, 작은 값 % 나머지 값을 재귀함수로 계속 진행
>
> 나머지가 0이 되면, 그때의 작은 값이 ''최대공약수''이다.
>
> **최소 공배수**는 간단하다. 주어진 값들끼리 곱한 값을 ''최대공약수''로 나누면 끝! 

```java
public static void main(String[] args) {
	int a = 24; int b = 18;
	int res = gcd(a,b);
	System.out.println("최대공약수 : " + res);
	System.out.println("최소공배수 : " + (a*b)/res); // a*b를 최대공약수로 나눈다
}

public static int gcd(int a, int b) { // 최대공약수
	
	if(a < b) swap(a,b)// b가 더 크면 swap
	
	int num = a%b;
	if(num == 0) return b;
	
	return gcd(b, num);
}
```','algorithm','') ON CONFLICT DO NOTHING;
