INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('2bb0be35-75b7-5813-af12-5ade3b8bad96','1','gyoogle','doc:gyoogle:3f7f03d3ffc1e567ba3fd254fb8150b81fb5305357d06997f6fa4c7676a8d727','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:470b721a454a93b5a9c188bc4fd3063c2c3b15b3c082e8c7fc8f7be7a7c3c61c','csas-gyoogle-bank-v1','컴퓨터의 구성','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%BB%B4%ED%93%A8%ED%84%B0%EC%9D%98%20%EA%B5%AC%EC%84%B1.md','Computer Science/Computer Architecture/컴퓨터의 구성.md#시스템 버스','#### 시스템 버스

