INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('54383061-4e54-53ea-89d3-fd34a6fcbdd2','54383061-4e54-53ea-89d3-fd34a6fcbdd2',1,'문서에서 ''ARM''이라는 이름은 무엇의 약자이며, 그 핵심은 무엇이라고 설명하고 있습니까?','COMPUTER_ARCHITECTURE','EASY','CURATED','READY','문서는 ARM이 ''Advanced RISC Machine''의 약자이고 핵심은 RISC(감소된 명령 집합)임을 명확히 밝힙니다. 다른 보기는 문서에 없는 잘못된 약자와 핵심을 제시하고 있습니다.

1. 문서에 ''Adaptive ROM Module''이라는 설명은 없습니다.
2. 문서에는 ''Advanced Register Manager''라는 설명이 없습니다.
3. 문서에 ''Asymmetric Resource Microchip''이라는 설명은 없습니다.
4. 정답: 문서에서 직접 언급한 ARM의 풀네임과 핵심입니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/ARM%20%ED%94%84%EB%A1%9C%EC%84%B8%EC%84%9C.md',now(),'{"slot": 8, "topic": "ARM 용어와 핵심", "learningObjective": "ARM 약자의 의미와 핵심 설계 철학(RISC)을 설명할 수 있다.", "difficulty": "EASY", "question": "문서에서 ''ARM''이라는 이름은 무엇의 약자이며, 그 핵심은 무엇이라고 설명하고 있습니까?", "options": ["Adaptive ROM Module의 약자이며 핵심은 ROM 기반 설계이다", "Advanced Register Manager의 약자이며 핵심은 레지스터 전용 설계이다", "Asymmetric Resource Microchip의 약자이며 핵심은 비대칭 자원 분배이다", "Advanced RISC Machine의 약자이며 핵심은 RISC 설계이다"], "correctAnswer": 4, "explanation": "문서는 ARM이 ''Advanced RISC Machine''의 약자이고 핵심은 RISC(감소된 명령 집합)임을 명확히 밝힙니다. 다른 보기는 문서에 없는 잘못된 약자와 핵심을 제시하고 있습니다.", "optionExplanations": ["문서에 ''Adaptive ROM Module''이라는 설명은 없습니다.", "문서에는 ''Advanced Register Manager''라는 설명이 없습니다.", "문서에 ''Asymmetric Resource Microchip''이라는 설명은 없습니다.", "정답: 문서에서 직접 언급한 ARM의 풀네임과 핵심입니다."], "keywords": ["ARM", "Advanced RISC Machine", "RISC"], "sourceEvidence": {"section": "ARM 프로세서", "quote": "ARM : Advanced RISC Machine\n\n즉, `진보된 RISC 기기`의 약자로 ARM의 핵심은 RISC이다."}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/ARM 프로세서.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/ARM%20%ED%94%84%EB%A1%9C%EC%84%B8%EC%84%9C.md", "id": "54383061-4e54-53ea-89d3-fd34a6fcbdd2", "review": {"blind": {"slot": 8, "position": 4, "unambiguous": true, "reason": "문서에 ''ARM : Advanced RISC Machine''이라 적고 핵심은 RISC라고 설명함."}, "evidenceAudit": {"slot": 8, "passed": true, "reason": "정답 ''Advanced RISC Machine''과 RISC 중심 설명이 원문에 명시되어 있고 나머지 보기들은 문서에 없는 잘못된 약자입니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:7de9ff9f8c8d28b9eeba58c88e8dbe311b6a5c85d34648be1c2ad3cac9607188"}'::jsonb) ON CONFLICT DO NOTHING;
