INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('a7061c3c-1ad1-5888-9ce7-1bfbfd7ff6cb','a7061c3c-1ad1-5888-9ce7-1bfbfd7ff6cb',1,'문서에 따르면 산술논리연산장치(ALU)의 주된 역할은 무엇입니까?','COMPUTER_ARCHITECTURE','EASY','CURATED','READY','문서에서 중앙처리장치는 비교와 연산을 담당하는 산술논리연산장치(ALU)와 제어장치, 레지스터로 구성되어 있다고 명시합니다. 따라서 ALU의 주된 역할은 비교와 연산 수행입니다. 2번은 제어장치의 역할에 해당하고, 3번은 보조기억장치의 특성, 4번은 버스의 역할과 관련된 설명입니다.

1. 정답입니다. 문서에서 ALU는 비교와 연산을 담당한다고 서술하고 있습니다.
2. 오답입니다. 이는 제어장치의 기능으로 문서에 따로 적혀 있습니다.
3. 오답입니다. 영구 저장은 보조기억장치의 장점으로 설명되어 있습니다.
4. 오답입니다. 입출력과 데이터 전달 경로는 시스템 버스의 역할입니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%BB%B4%ED%93%A8%ED%84%B0%EC%9D%98%20%EA%B5%AC%EC%84%B1.md',now(),'{"slot": 13, "topic": "CPU 구성요소", "learningObjective": "ALU의 기본 기능을 설명할 수 있다", "difficulty": "EASY", "question": "문서에 따르면 산술논리연산장치(ALU)의 주된 역할은 무엇입니까?", "options": ["비교와 연산을 담당한다.", "명령어의 해석과 실행을 담당한다.", "프로그램과 데이터를 영구적으로 저장한다.", "입출력 장치와 데이터를 주고받는 통로를 제공한다."], "correctAnswer": 1, "explanation": "문서에서 중앙처리장치는 비교와 연산을 담당하는 산술논리연산장치(ALU)와 제어장치, 레지스터로 구성되어 있다고 명시합니다. 따라서 ALU의 주된 역할은 비교와 연산 수행입니다. 2번은 제어장치의 역할에 해당하고, 3번은 보조기억장치의 특성, 4번은 버스의 역할과 관련된 설명입니다.", "optionExplanations": ["정답입니다. 문서에서 ALU는 비교와 연산을 담당한다고 서술하고 있습니다.", "오답입니다. 이는 제어장치의 기능으로 문서에 따로 적혀 있습니다.", "오답입니다. 영구 저장은 보조기억장치의 장점으로 설명되어 있습니다.", "오답입니다. 입출력과 데이터 전달 경로는 시스템 버스의 역할입니다."], "keywords": ["ALU", "비교", "연산"], "sourceEvidence": {"section": "중앙처리장치(CPU)", "quote": "중앙처리장치는 비교와 연산을 담당하는 <strong>산술논리연산장치(ALU)</strong>와 명령어의 해석과 실행을 담당하는 **제어장치**"}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/컴퓨터의 구성.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%BB%B4%ED%93%A8%ED%84%B0%EC%9D%98%20%EA%B5%AC%EC%84%B1.md", "id": "a7061c3c-1ad1-5888-9ce7-1bfbfd7ff6cb", "review": {"blind": {"slot": 13, "position": 1, "unambiguous": true, "reason": "문서에서 ALU는 ''비교와 연산을 담당''한다고 명시함."}, "evidenceAudit": {"slot": 13, "passed": true, "reason": "정답(옵션 1), 근거 문구, 모든 선택지 설명이 원문 근거와 일치하여 문제·해설이 정확함."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:3f7f03d3ffc1e567ba3fd254fb8150b81fb5305357d06997f6fa4c7676a8d727"}'::jsonb) ON CONFLICT DO NOTHING;
