INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('e1a5a424-017b-5c07-861c-faafbde6bc87','1','gyoogle','doc:gyoogle:6550dfeab971b7c00735a27f01a29df2e6cba25dabea0d6626d52c61b2fbfed2','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:f5c98c133ab8c5bcb4b2cf4fb33ef03505938d49b84fcbee7f9e454c486e73e8','csas-gyoogle-bank-v1','패리티 비트 & 해밍 코드','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%ED%8C%A8%EB%A6%AC%ED%8B%B0%20%EB%B9%84%ED%8A%B8%20%26%20%ED%95%B4%EB%B0%8D%20%EC%BD%94%EB%93%9C.md','Computer Science/Computer Architecture/패리티 비트 & 해밍 코드.md#해밍 코드','### 해밍 코드

> 데이터 전송 시 1비트의 에러를 정정할 수 있는 자기 오류정정 코드를 말한다.
>
> 패리티비트를 보고, 1비트에 대한 오류를 정정할 곳을 찾아 수정할 수 있다.
> (패리티 비트는 오류를 검출하기만 할 뿐 수정하지는 않기 때문에 해밍 코드를 활용)

<br>','computer-architecture','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-eccd4bfc50a06b02','gyoogle-eccd4bfc50a06b02','중앙처리장치(CPU) 작동 원리','중앙처리장치(CPU) 작동 원리','COMPUTER_ARCHITECTURE','gyoogle: 중앙처리장치(CPU) 작동 원리') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('f0ef8460-0577-57e1-8ca7-d64d643b75a2','f0ef8460-0577-57e1-8ca7-d64d643b75a2',1,'인출 사이클의 표준 시퀀스에 대한 설명으로 옳은 것은 무엇입니까?','COMPUTER_ARCHITECTURE','MEDIUM','CURATED','READY','원문은 인출 사이클의 구체적 순서로 T0: MAR ← PC, T1: MBR ← M[MAR], PC ← PC+1, T2: IR ← MBR을 제시하고 있으며, 또한 인출 사이클에서 가장 중요한 부분은 PC 값 증가라고 명시하고 있습니다. 따라서 첫 번째 선택지가 옳습니다. 다른 선택지들은 원문 절차와 일치하지 않습니다.

1. 정답입니다. 원문에서 인출 순서를 "T0 : MAR ← PC", "T1 : MBR ← M[MAR], PC ← PC+1", "T2 : IR ← MBR"로 제시하고 있습니다.
2. 틀렸습니다. 원문은 MAR에 PC를 넣는다고 되어 있으며 PC에 MAR을 넣는 순서는 잘못된 표현입니다. 또한 MBR 사용을 명시하고 있습니다.
3. 틀렸습니다. 원문은 인출 사이클에서 PC 값을 증가시킨다고 명시하고 있으며 감소시킨다고 하지 않습니다.
4. 틀렸습니다. 인출 사이클은 명령어를 주기억장치에서 가져와 IR에 저장하는 과정으로, AC에 곧바로 더하는 동작은 실행 사이클의 일부(예: ADD 명령)입니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md',now(),'{"slot": 25, "topic": "인출 사이클에서의 레지스터 동작", "learningObjective": "인출 사이클의 기본 시퀀스와 PC 증가의 역할을 설명할 수 있다", "difficulty": "MEDIUM", "question": "인출 사이클의 표준 시퀀스에 대한 설명으로 옳은 것은 무엇입니까?", "options": ["MAR에 PC를 넣고, 해당 메모리의 내용을 MBR로 가져오며 PC를 증가시키고, 그 후 MBR을 IR로 옮긴다.", "PC에 MAR을 넣고, IR을 통해 메모리에서 직접 명령어를 실행하며 MBR은 사용하지 않는다.", "인출 사이클에서는 PC 값을 감소시켜 이전 명령어 주소를 가리키도록 한다.", "인출 사이클은 메모리에서 데이터를 읽어 AC로 곧바로 더하는 동작으로 구성된다."], "correctAnswer": 1, "explanation": "원문은 인출 사이클의 구체적 순서로 T0: MAR ← PC, T1: MBR ← M[MAR], PC ← PC+1, T2: IR ← MBR을 제시하고 있으며, 또한 인출 사이클에서 가장 중요한 부분은 PC 값 증가라고 명시하고 있습니다. 따라서 첫 번째 선택지가 옳습니다. 다른 선택지들은 원문 절차와 일치하지 않습니다.", "optionExplanations": ["정답입니다. 원문에서 인출 순서를 \"T0 : MAR ← PC\", \"T1 : MBR ← M[MAR], PC ← PC+1\", \"T2 : IR ← MBR\"로 제시하고 있습니다.", "틀렸습니다. 원문은 MAR에 PC를 넣는다고 되어 있으며 PC에 MAR을 넣는 순서는 잘못된 표현입니다. 또한 MBR 사용을 명시하고 있습니다.", "틀렸습니다. 원문은 인출 사이클에서 PC 값을 증가시킨다고 명시하고 있으며 감소시킨다고 하지 않습니다.", "틀렸습니다. 인출 사이클은 명령어를 주기억장치에서 가져와 IR에 저장하는 과정으로, AC에 곧바로 더하는 동작은 실행 사이클의 일부(예: ADD 명령)입니다."], "keywords": ["인출 사이클", "MAR", "MBR", "PC", "IR"], "sourceEvidence": {"section": "인출 사이클과 실행 사이클에 의한 명령어 처리 과정", "quote": "T0 : MAR ← PC\nT1 : MBR ← M[MAR], PC ← PC+1\nT2 : IR ← MBR"}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md", "id": "f0ef8460-0577-57e1-8ca7-d64d643b75a2", "review": {"blind": {"slot": 25, "position": 1, "unambiguous": true, "reason": "인출 순서 T0:T1:T2가 원문에 그대로 있으며 PC 증가가 T1에 있음."}, "evidenceAudit": {"slot": 25, "passed": true, "reason": "정답(옵션 1)과 그 설명 및 각 오답 해설이 원문에 제시된 인출 사이클(T0/T1/T2) 절차와 PC 증가 내용과 정확히 일치합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366"}'::jsonb) ON CONFLICT DO NOTHING;
