INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('9ff83313-0116-52b8-b743-482027e6ccec','edcb8404-72ab-532b-bd5f-bea3d51c67bd',3,'MAR은 주기억장치에서 읽기/쓰기를 수행할 주소를 저장하고, MBR은 주기억장치에서 읽어온 데이터 또는 저장할 데이터를 임시 저장한다.',true) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('4a27ebb9-0d55-5b57-b72b-1fb3decb6ba6','edcb8404-72ab-532b-bd5f-bea3d51c67bd',4,'MBR은 주기억장치의 주소를 저장하고, MAR은 읽어온 데이터를 임시 저장한다.',false) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_concepts(quiz_id,concept_id,is_primary) VALUES ('edcb8404-72ab-532b-bd5f-bea3d51c67bd','concept:gyoogle-eccd4bfc50a06b02',true) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('edcb8404-72ab-532b-bd5f-bea3d51c67bd','1','gyoogle','doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:8986824ee7a9a5f6293ec1276e374d85bd09c8d8271f631e04774e362c484dd2','csas-gyoogle-bank-v1','중앙처리장치(CPU) 작동 원리','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md','Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md#특수 목적 레지스터 중 중요한 것들','#### 특수 목적 레지스터 중 중요한 것들

- MAR(메모리 주소 레지스터) : 읽기와 쓰기 연산을 수행할 주기억장치 주소 저장
- PC(프로그램 카운터) : 다음에 수행할 명령어 주소 저장
- IR(명령어 레지스터) : 현재 실행 중인 명령어 저장
- MBR(메모리 버퍼 레지스터) : 주기억장치에서 읽어온 데이터 or 저장할 데이터 임시 저장
- AC(누산기) : 연산 결과 임시 저장','computer-architecture','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-661f7cd97268d3c8','gyoogle-661f7cd97268d3c8','고정 소수점 & 부동 소수점','고정 소수점 & 부동 소수점','COMPUTER_ARCHITECTURE','gyoogle: 고정 소수점 & 부동 소수점') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('e3963b26-e13b-57bc-88fb-8434afc9e07e','e3963b26-e13b-57bc-88fb-8434afc9e07e',1,'다음 중 자료에서 고정 소수점이 주로 사용되는 상황에 포함되지 않는 것은 무엇입니까?','COMPUTER_ARCHITECTURE','MEDIUM','CURATED','READY','자료는 고정 소수점의 사용 상황으로 임베디드 시스템·마이크로컨트롤러, 실시간 시스템, 비용 민감형 하드웨어, DSP 등을 명시하고 있으며, 과학적 계산과 시뮬레이션은 부동 소수점 사용 사례로 분류되어 있습니다. 따라서 과학적 계산과 물리 시뮬레이션은 고정 소수점의 사용 사례에 포함되지 않습니다.

1. 자료에 임베디드 시스템과 마이크로컨트롤러는 고정 소수점 사용 상황으로 명확히 적혀 있습니다.
2. 자료에는 실시간 시스템에서 예측 가능한 실행 시간이 중요해 고정 소수점 연산이 선호된다고 명시되어 있습니다.
3. 자료는 일부 DSP 알고리즘이 고정 소수점으로 충분할 수 있다고 예로 들며 고정 소수점 사용 사례로 포함하고 있습니다.
4. 정답입니다. 자료는 과학적 계산과 시뮬레이션을 부동 소수점 사용 상황으로 분류하고 있어 고정 소수점의 일반적 사용 사례에 포함되지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EA%B3%A0%EC%A0%95%20%EC%86%8C%EC%88%98%EC%A0%90%20%26%20%EB%B6%80%EB%8F%99%20%EC%86%8C%EC%88%98%EC%A0%90.md',now(),'{"slot": 28, "topic": "고정 소수점의 사용 사례", "learningObjective": "고정 소수점이 선호되는 구체적 응용 분야를 열거할 수 있다.", "difficulty": "MEDIUM", "question": "다음 중 자료에서 고정 소수점이 주로 사용되는 상황에 포함되지 않는 것은 무엇입니까?", "options": ["임베디드 시스템과 마이크로컨트롤러", "실시간 시스템", "디지털 신호 처리(DSP)", "과학적 계산과 물리 시뮬레이션"], "correctAnswer": 4, "explanation": "자료는 고정 소수점의 사용 상황으로 임베디드 시스템·마이크로컨트롤러, 실시간 시스템, 비용 민감형 하드웨어, DSP 등을 명시하고 있으며, 과학적 계산과 시뮬레이션은 부동 소수점 사용 사례로 분류되어 있습니다. 따라서 과학적 계산과 물리 시뮬레이션은 고정 소수점의 사용 사례에 포함되지 않습니다.", "optionExplanations": ["자료에 임베디드 시스템과 마이크로컨트롤러는 고정 소수점 사용 상황으로 명확히 적혀 있습니다.", "자료에는 실시간 시스템에서 예측 가능한 실행 시간이 중요해 고정 소수점 연산이 선호된다고 명시되어 있습니다.", "자료는 일부 DSP 알고리즘이 고정 소수점으로 충분할 수 있다고 예로 들며 고정 소수점 사용 사례로 포함하고 있습니다.", "정답입니다. 자료는 과학적 계산과 시뮬레이션을 부동 소수점 사용 상황으로 분류하고 있어 고정 소수점의 일반적 사용 사례에 포함되지 않습니다."], "keywords": ["고정 소수점", "임베디드", "실시간", "DSP", "사용 사례"], "sourceEvidence": {"section": "고정 소수점 & 부동 소수점.md", "startLine": 50, "endLine": 61, "quote": "**고정 소수점 사용 상황.**\n1. 임베디드 시스켐과 마이크로컨트롤러\n    - 메모리와 처리 능력이 제한된 환경에서 고정 소수점 연산이 일반적입니다. 이는 부동 소수점 연산을 지원하는 하드웨어가 없거나, 그러한 연산이 배터리 수명이나 다른 자원을 과도하게 소모할 수 있기 때문입니다.\n\n2. 실시간 시스템\n    - 예측 가능한 실행 시간이 중요한 실시간 응용 프로그램에서는 고정 소수점 연산이 선호됩니다. 이는 부동 소수점 연산이 가변적인 실행 시간을 가질 수 있기 때문입니다.\n\n3. 비용 민감형 하드웨어\n    - 부동 소수점 연산자를 지원하는 비용이 더 들 수 있어, 가격을 낮추기 위해 고정 소수점 연산을 사용하는 경우가 있습니다.\n\n4. 디지털 신호 처리(DSP)\n    - 일부 디지털 신호 처리 알고리즘은 정확하게 정의된 범위 내의 값을 사용하기 때문에 고정 소수점 연산으로 충분한 경우가 많습니다."}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/고정 소수점 & 부동 소수점.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EA%B3%A0%EC%A0%95%20%EC%86%8C%EC%88%98%EC%A0%90%20%26%20%EB%B6%80%EB%8F%99%20%EC%86%8C%EC%88%98%EC%A0%90.md", "id": "e3963b26-e13b-57bc-88fb-8434afc9e07e", "review": {"blind": {"slot": 28, "correctOptionText": "과학적 계산과 물리 시뮬레이션", "unambiguous": true, "reason": "자료는 고정 소수점의 사용 사례로 임베디드, 실시간, 비용 민감형 하드웨어, DSP를 들고 과학적 계산·시뮬레이션은 부동 소수점 사용 사례로 분류합니다.", "position": 4}, "evidenceAudit": {"slot": 28, "passed": true, "reason": "Source enumerates embedded, real-time, cost-sensitive, DSP as fixed-point use cases and places scientific simulation under floating-point; correct option reflects that and distractors are present in the source."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:661f7cd97268d3c8a111c4af94e3d24dfcf5283b0149e548a8855758c7685ef3"}'::jsonb) ON CONFLICT DO NOTHING;
