INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('1a1fc524-81bd-5a82-b87d-a8470292a156','1','gyoogle','doc:gyoogle:3f7f03d3ffc1e567ba3fd254fb8150b81fb5305357d06997f6fa4c7676a8d727','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:27df8abfbdb52682e18a335e3dee11b36d6d4c2d8276d4bbdbcb12d46e5751c2','csas-gyoogle-bank-v1','컴퓨터의 구성','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%BB%B4%ED%93%A8%ED%84%B0%EC%9D%98%20%EA%B5%AC%EC%84%B1.md','Computer Science/Computer Architecture/컴퓨터의 구성.md#주소 버스','##### 주소 버스

데이터를 정확히 실어나르기 위해서는 기억장치 ''주소''를 정해주어야 함.

주소버스는 중앙처리장치가 주기억장치나 입출력장치로 기억장치 주소를 전달하는 통로이기 때문에 ''단방향'' 버스임','computer-architecture','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-eccd4bfc50a06b02','gyoogle-eccd4bfc50a06b02','중앙처리장치(CPU) 작동 원리','중앙처리장치(CPU) 작동 원리','COMPUTER_ARCHITECTURE','gyoogle: 중앙처리장치(CPU) 작동 원리') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('554893eb-5179-5d8c-af17-966c05cde291','554893eb-5179-5d8c-af17-966c05cde291',1,'원문에 따른 ADD addr 명령어의 실행 과정으로 옳은 순서는 무엇입니까?','COMPUTER_ARCHITECTURE','MEDIUM','CURATED','READY','원문은 ADD addr의 실행을 "T0 : MAR ← IR(Addr)", "T1 : MBR ← M[MAR]", "T2 : AC ← AC + MBR"로 제시합니다. 따라서 먼저 MAR에 주소를 넣고 메모리에서 값을 읽어 MBR에 저장한 뒤 AC에 더하는 과정이 정확합니다. 다른 선택지는 원문 절차와 일치하지 않습니다.

1. 틀렸습니다. 원문은 PC를 사용하는 절차가 아니며 PC에 IR(Addr)을 넣는다는 설명은 없습니다.
2. 틀렸습니다. MBR에 AC를 저장하고 메모리에 쓰는 과정은 STA 명령어의 흐름에 해당하며 ADD와는 다릅니다.
3. 틀렸습니다. 원문은 메모리에서 값을 읽어와 MBR에 저장한 뒤 AC에 더한다고 명시하고 있으므로 메모리 접근을 생략하지 않습니다.
4. 정답입니다. 원문에 ADD 연산은 T0에 MAR에 주소를 넣고, T1에 메모리에서 MBR로 읽어오며, T2에 AC ← AC + MBR이라고 되어 있습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md',now(),'{"slot": 32, "topic": "실행 사이클: ADD 명령어의 동작", "learningObjective": "ADD 명령어 실행 시 레지스터 간 데이터 흐름을 설명할 수 있다", "difficulty": "MEDIUM", "question": "원문에 따른 ADD addr 명령어의 실행 과정으로 옳은 순서는 무엇입니까?", "options": ["PC에 IR(Addr)을 넣고 바로 AC에 값이 더해진다.", "MBR에 AC를 저장하고 그 값을 메모리에 쓰는 과정이 먼저 실행된다.", "IR(Addr)을 AC에 직접 더하고 메모리 접근은 생략된다.", "MAR에 IR(Addr)을 넣고, 해당 메모리의 내용을 MBR로 읽어온 다음 AC에 MBR을 더한다."], "correctAnswer": 4, "explanation": "원문은 ADD addr의 실행을 \"T0 : MAR ← IR(Addr)\", \"T1 : MBR ← M[MAR]\", \"T2 : AC ← AC + MBR\"로 제시합니다. 따라서 먼저 MAR에 주소를 넣고 메모리에서 값을 읽어 MBR에 저장한 뒤 AC에 더하는 과정이 정확합니다. 다른 선택지는 원문 절차와 일치하지 않습니다.", "optionExplanations": ["틀렸습니다. 원문은 PC를 사용하는 절차가 아니며 PC에 IR(Addr)을 넣는다는 설명은 없습니다.", "틀렸습니다. MBR에 AC를 저장하고 메모리에 쓰는 과정은 STA 명령어의 흐름에 해당하며 ADD와는 다릅니다.", "틀렸습니다. 원문은 메모리에서 값을 읽어와 MBR에 저장한 뒤 AC에 더한다고 명시하고 있으므로 메모리 접근을 생략하지 않습니다.", "정답입니다. 원문에 ADD 연산은 T0에 MAR에 주소를 넣고, T1에 메모리에서 MBR로 읽어오며, T2에 AC ← AC + MBR이라고 되어 있습니다."], "keywords": ["ADD", "MAR", "MBR", "AC"], "sourceEvidence": {"section": "인출한 이후, 명령어를 실행하는 과정", "quote": "T0 : MAR ← IR(Addr)\nT1 : MBR ← M[MAR]\nT2 : AC ← AC + MBR"}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md", "id": "554893eb-5179-5d8c-af17-966c05cde291", "review": {"blind": {"slot": 32, "position": 4, "unambiguous": true, "reason": "ADD addr의 실행 단계가 T0:T1:T2로 원문에 ‘MAR ← IR(Addr); MBR ← M[MAR]; AC ← AC + MBR’라고 명시됨."}, "evidenceAudit": {"slot": 32, "passed": true, "reason": "정답(옵션 4)과 설명 및 오답 해설이 원문의 ADD 실행 절차(T0: MAR←IR(Addr), T1: MBR←M[MAR], T2: AC←AC+MBR)를 정확히 반영합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366"}'::jsonb) ON CONFLICT DO NOTHING;
