INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('763d8f2d-c826-5b9c-9fbe-057d601a8737','554893eb-5179-5d8c-af17-966c05cde291',2,'MBR에 AC를 저장하고 그 값을 메모리에 쓰는 과정이 먼저 실행된다.',false) ON CONFLICT DO NOTHING;
