INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('554893eb-5179-5d8c-af17-966c05cde291','1','gyoogle','doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:09fcbf7c12a9ed64ea845ee9e5f533eb605f556b9d22f23df3cc1252df0e1dac','csas-gyoogle-bank-v1','중앙처리장치(CPU) 작동 원리','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md','Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md#인출한 이후, 명령어를 실행하는 과정','##### 인출한 이후, 명령어를 실행하는 과정

> ADD addr 명령어 연산

```
T0 : MAR ← IR(Addr)
T1 : MBR ← M[MAR]
T2 : AC ← AC + MBR
```

이미 인출이 진행되고 명령어만 실행하면 되기 때문에 PC를 증가할 필요x

IR에 MBR의 값이 이미 저장된 상태를 의미함

따라서 AC에 MBR을 더해주기만 하면 됨

> LOAD addr 명령어 연산

```
T0 : MAR ← IR(Addr)
T1 : MBR ← M[MAR]
T2 : AC ← MBR
```

기억장치에 있는 데이터를 AC로 이동하는 명령어

> STA addr 명령어 연산

```
T0 : MAR ← IR(Addr)
T1 : MBR ← AC
T2 : M[MAR] ← MBR
```

AC에 있는 데이터를 기억장치로 저장하는 명령어

> JUMP addr 명령어 연산

```
T0 : PC ← IR(Addr)
```

PC값을 IR의 주소값으로 변경하는 분기 명령어','computer-architecture','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-eccd4bfc50a06b02','gyoogle-eccd4bfc50a06b02','중앙처리장치(CPU) 작동 원리','중앙처리장치(CPU) 작동 원리','COMPUTER_ARCHITECTURE','gyoogle: 중앙처리장치(CPU) 작동 원리') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('e8125783-0d29-5ee4-89d5-283d896c8086','e8125783-0d29-5ee4-89d5-283d896c8086',1,'인출 사이클의 마이크로연산 중 MBR에 저장된 내용을 명령어 레지스터(IR)로 전달하는 단계는 어떤 타이밍(Tx)에 해당합니까?','COMPUTER_ARCHITECTURE','MEDIUM','CURATED','READY','본문의 인출 사이클 마이크로연산 예시에서 T0은 MAR ← PC, T1은 MBR ← M[MAR], PC ← PC+1, T2는 IR ← MBR로 명시되어 있어 MBR→IR 전달은 T2 단계입니다.

1. 정답: 본문 예시에서 T2 단계가 IR ← MBR로 정의되어 있습니다.
2. 오답: T0은 MAR ← PC로 정의되어 있어 MBR→IR 전달과 관련이 없습니다.
3. 오답: T1은 메모리에서 MBR로 읽어오는 단계와 PC 증가를 포함하며 MBR→IR 전달은 아닙니다.
4. 오답: 본문에 T3 단계는 언급되어 있지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md',now(),'{"slot": 33, "topic": "인출 사이클의 마이크로연산", "learningObjective": "인출 사이클에서 명령어를 MBR에서 IR로 전달하는 마이크로연산을 식별할 수 있다.", "difficulty": "MEDIUM", "question": "인출 사이클의 마이크로연산 중 MBR에 저장된 내용을 명령어 레지스터(IR)로 전달하는 단계는 어떤 타이밍(Tx)에 해당합니까?", "options": ["T2", "T0", "T1", "T3"], "correctAnswer": 1, "explanation": "본문의 인출 사이클 마이크로연산 예시에서 T0은 MAR ← PC, T1은 MBR ← M[MAR], PC ← PC+1, T2는 IR ← MBR로 명시되어 있어 MBR→IR 전달은 T2 단계입니다.", "optionExplanations": ["정답: 본문 예시에서 T2 단계가 IR ← MBR로 정의되어 있습니다.", "오답: T0은 MAR ← PC로 정의되어 있어 MBR→IR 전달과 관련이 없습니다.", "오답: T1은 메모리에서 MBR로 읽어오는 단계와 PC 증가를 포함하며 MBR→IR 전달은 아닙니다.", "오답: 본문에 T3 단계는 언급되어 있지 않습니다."], "keywords": ["인출 사이클", "MBR", "IR", "T2"], "sourceEvidence": {"section": "중앙처리장치(CPU) 작동 원리.md", "startLine": 98, "endLine": 102, "quote": "```\nT0 : MAR ← PC\nT1 : MBR ← M[MAR], PC ← PC+1\nT2 : IR ← MBR\n```"}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md", "id": "e8125783-0d29-5ee4-89d5-283d896c8086", "review": {"blind": {"slot": 33, "correctOptionText": "T2", "unambiguous": true, "reason": "인출 사이클 순서에서 T2 : IR ← MBR로 MBR 내용을 IR로 전달한다고 정확히 기술됨.", "position": 1}, "evidenceAudit": {"slot": 33, "passed": true, "reason": "인출 사이클의 마이크로연산에서 ''IR ← MBR''이 T2로 명시되어 있어 정답(T2·옵션1)과 모든 선택지 해설이 소스에 의해 검증 가능합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366"}'::jsonb) ON CONFLICT DO NOTHING;
