INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('b04e616f-b31d-5e53-bd58-72c8a30ad789','1','gyoogle','doc:gyoogle:85238e5b2a3f0341e9be7cd73f09dcec0034af74f3178d1b6e699b82eb2a1893','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:e7ef20b9f7314cd7449e829a03d3a5de83fd6e108ae2958a3226142e6f4722f9','csas-gyoogle-bank-v1','캐시 메모리(Cache Memory)','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%BA%90%EC%8B%9C%20%EB%A9%94%EB%AA%A8%EB%A6%AC%28Cache%20Memory%29.md','Computer Science/Computer Architecture/캐시 메모리(Cache Memory).md#캐시 메모리 작동 원리','#### 캐시 메모리 작동 원리

- ##### 시간 지역성

  for나 while 같은 반복문에 사용하는 조건 변수처럼 한번 참조된 데이터는 잠시후 또 참조될 가능성이 높음

- ##### 공간 지역성

  A[0], A[1]과 같은 연속 접근 시, 참조된 데이터 근처에 있는 데이터가 잠시후 또 사용될 가능성이 높음

> 이처럼 참조 지역성의 원리가 존재한다.

<br>

캐시에 데이터를 저장할 때는, 이러한 참조 지역성(공간)을 최대한 활용하기 위해 해당 데이터뿐만 아니라, 옆 주소의 데이터도 같이 가져와 미래에 쓰일 것을 대비한다.

CPU가 요청한 데이터가 캐시에 있으면 ''Cache Hit'', 없어서 DRAM에서 가져오면 ''Cache Miss''

<br>','computer-architecture','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-eccd4bfc50a06b02','gyoogle-eccd4bfc50a06b02','중앙처리장치(CPU) 작동 원리','중앙처리장치(CPU) 작동 원리','COMPUTER_ARCHITECTURE','gyoogle: 중앙처리장치(CPU) 작동 원리') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('3d129d78-57ea-51b4-9a9e-2a6eaac26fdf','3d129d78-57ea-51b4-9a9e-2a6eaac26fdf',1,'ADD addr 명령어가 실행될 때 일어나는 올바른 연산 순서는 무엇입니까?','COMPUTER_ARCHITECTURE','MEDIUM','CURATED','READY','본문의 ADD 연산 예시는 T0: MAR ← IR(Addr), T1: MBR ← M[MAR], T2: AC ← AC + MBR 순서로, 주소를 MAR로 전달하고 해당 메모리 내용을 MBR에 읽은 뒤 AC에 더하는 순서가 맞습니다.

1. 오답: MBR에 주소를 저장하거나 MAR에 데이터를 저장한다는 기술은 본문에 없습니다.
2. 오답: IR에 직접 메모리 내용을 쓰고 PC를 0으로 초기화한다는 동작은 본문에 없습니다.
3. 정답: 본문 T0~T2 순서가 정확히 이 흐름을 설명합니다.
4. 오답: PC에 주소 전달이나 AC 값을 메모리에 저장하는 순서는 ADD 연산 예시와 일치하지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md',now(),'{"slot": 39, "topic": "ADD 명령어 실행 흐름", "learningObjective": "ADD addr 명령어 실행 시 레지스터 간 데이터 흐름을 순서대로 설명할 수 있다.", "difficulty": "MEDIUM", "question": "ADD addr 명령어가 실행될 때 일어나는 올바른 연산 순서는 무엇입니까?", "options": ["MBR에 주소 저장 → MAR에 데이터 저장 → AC를 초기화", "IR에 직접 메모리 내용을 쓰고 PC를 0으로 초기화", "MAR에 주소 전달 → 해당 주소의 내용을 MBR로 읽음 → AC에 MBR을 더함", "PC에 주소 전달 → AC의 값을 메모리에 저장 → MBR에 더함"], "correctAnswer": 3, "explanation": "본문의 ADD 연산 예시는 T0: MAR ← IR(Addr), T1: MBR ← M[MAR], T2: AC ← AC + MBR 순서로, 주소를 MAR로 전달하고 해당 메모리 내용을 MBR에 읽은 뒤 AC에 더하는 순서가 맞습니다.", "optionExplanations": ["오답: MBR에 주소를 저장하거나 MAR에 데이터를 저장한다는 기술은 본문에 없습니다.", "오답: IR에 직접 메모리 내용을 쓰고 PC를 0으로 초기화한다는 동작은 본문에 없습니다.", "정답: 본문 T0~T2 순서가 정확히 이 흐름을 설명합니다.", "오답: PC에 주소 전달이나 AC 값을 메모리에 저장하는 순서는 ADD 연산 예시와 일치하지 않습니다."], "keywords": ["ADD", "MAR", "MBR", "AC"], "sourceEvidence": {"section": "중앙처리장치(CPU) 작동 원리.md", "startLine": 112, "endLine": 116, "quote": "```\nT0 : MAR ← IR(Addr)\nT1 : MBR ← M[MAR]\nT2 : AC ← AC + MBR\n```"}, "category": "COMPUTER_ARCHITECTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Computer Architecture/중앙처리장치(CPU) 작동 원리.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Computer%20Architecture/%EC%A4%91%EC%95%99%EC%B2%98%EB%A6%AC%EC%9E%A5%EC%B9%98%28CPU%29%20%EC%9E%91%EB%8F%99%20%EC%9B%90%EB%A6%AC.md", "id": "3d129d78-57ea-51b4-9a9e-2a6eaac26fdf", "review": {"blind": {"slot": 39, "correctOptionText": "MAR에 주소 전달 → 해당 주소의 내용을 MBR로 읽음 → AC에 MBR을 더함", "unambiguous": true, "reason": "ADD addr 명령어의 마이크로연산이 T0:T2로 ''MAR ← IR(Addr)'', ''MBR ← M[MAR]'', ''AC ← AC + MBR''로 설명되어 있음.", "position": 3}, "evidenceAudit": {"slot": 39, "passed": true, "reason": "ADD 연산의 T0~T2 순서(MAR←IR(Addr), MBR←M[MAR], AC←AC+MBR)가 소스에 그대로 있어 정답(옵션3)과 해설이 정확합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:eccd4bfc50a06b02762ee61c4535b90df1518181d17d6e6e7226403860773366"}'::jsonb) ON CONFLICT DO NOTHING;
