INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('8903eca7-2578-5120-8d00-d89823576e7f','8903eca7-2578-5120-8d00-d89823576e7f',1,'후보키(Candidate Key)가 갖추어야 하는 두 가지 조건으로 옳은 것은 무엇입니까?','DATABASE','EASY','CURATED','READY','후보키는 튜플을 유일하게 식별하기 위한 속성의 부분집합이며, 문서에는 ''유일성''과 ''최소성''을 만족해야 한다고 명시되어 있습니다. 따라서 이 두 가지 조건이 후보키의 필수 조건입니다.

1. 틀렸습니다. 후보키는 중복이나 NULL을 허용하면 안 되는 특성이므로 해당 표현은 맞지 않습니다.
2. 틀렸습니다. 정규화와 인덱스화는 후보키 조건으로 문서에 기술되어 있지 않습니다.
3. 정답입니다. 문서에 ''2가지 조건 만족: 유일성, 최소성''이라고 명시되어 있습니다.
4. 틀렸습니다. ''무결성, 참조성''은 후보키의 두 가지 조건으로 문서에 언급되어 있지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/%5BDB%5D%20Key.md',now(),'{"slot": 15, "topic": "Candidate Key의 조건", "learningObjective": "Candidate Key가 충족해야 할 조건(유일성, 최소성)을 식별할 수 있다", "difficulty": "EASY", "question": "후보키(Candidate Key)가 갖추어야 하는 두 가지 조건으로 옳은 것은 무엇입니까?", "options": ["중복허용, NULL 허용", "정규화, 인덱스화", "유일성, 최소성", "무결성, 참조성"], "correctAnswer": 3, "explanation": "후보키는 튜플을 유일하게 식별하기 위한 속성의 부분집합이며, 문서에는 ''유일성''과 ''최소성''을 만족해야 한다고 명시되어 있습니다. 따라서 이 두 가지 조건이 후보키의 필수 조건입니다.", "optionExplanations": ["틀렸습니다. 후보키는 중복이나 NULL을 허용하면 안 되는 특성이므로 해당 표현은 맞지 않습니다.", "틀렸습니다. 정규화와 인덱스화는 후보키 조건으로 문서에 기술되어 있지 않습니다.", "정답입니다. 문서에 ''2가지 조건 만족: 유일성, 최소성''이라고 명시되어 있습니다.", "틀렸습니다. ''무결성, 참조성''은 후보키의 두 가지 조건으로 문서에 언급되어 있지 않습니다."], "keywords": ["Candidate Key", "유일성", "최소성"], "sourceEvidence": {"section": "1. Candidate Key (후보키)", "quote": "Tuple을 유일하게 식별하기 위해 사용하는 속성들의 부분 집합. (기본키로 사용할 수 있는 속성들)\n\n2가지 조건 만족\n\n* 유일성 : Key로 하나의 Tuple을 유일하게 식별할 수 있음\n* 최소성 : 꼭 필요한 속성으로만 구성"}, "category": "DATABASE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Database/[DB] Key.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/%5BDB%5D%20Key.md", "id": "8903eca7-2578-5120-8d00-d89823576e7f", "review": {"blind": {"slot": 15, "position": 3, "unambiguous": true, "reason": "Source 정의: Candidate Key는 유일성 및 최소성을 만족해야 함."}, "evidenceAudit": {"slot": 15, "passed": true, "reason": "Correct answer matches the source (''유일성'' and ''최소성'') and each distractor is contradicted or not stated in the source."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:99d418dd6a574d8fbe5eb23fbed29ff7e58ec1d01dec4922e6d1b1df31492375"}'::jsonb) ON CONFLICT DO NOTHING;
