INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('4b5abc3f-0e00-5a98-b0a6-5b479b7ca470','1','gyoogle','doc:gyoogle:7747596ac17774d07832bce07aafc9e7939e62a172ad6f9e47d871796e5aa4fe','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:872e64a0b5a2cb272f6486320d278877951dd903f1c069e6dccf013c7a189d87','csas-gyoogle-bank-v1','저장 프로시저(Stored PROCEDURE)','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/%EC%A0%80%EC%9E%A5%20%ED%94%84%EB%A1%9C%EC%8B%9C%EC%A0%80%28Stored%20PROCEDURE%29.md','Computer Science/Database/저장 프로시저(Stored PROCEDURE).md#예시1 (IN)','#### 예시1 (IN)

```plsql
CREATE OR REPLACE PROCEDURE test( name IN VARCHAR2 ) 
IS
	msg VARCHAR2(5) := ''내 이름은'';
BEGIN 
	dbms_output.put_line(msg||'' ''||name); 
END;

EXEC test(''규글'');
```

```
내 이름은 규글
```

<br>','database','') ON CONFLICT DO NOTHING;
