INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('46169513-ee6f-5e35-975d-82113c6ee4ed','46169513-ee6f-5e35-975d-82113c6ee4ed',1,'공격자가 로그인 WHERE 절에 OR 문과 ''1'' = ''1'' 같은 구문을 추가하여 인증을 우회하는 이유로 가장 적절한 설명은 무엇입니까?','DATABASE','MEDIUM','CURATED','READY','문서에서 설명하듯이 WHERE 절에 OR문을 추가하여 ''1'' = ''1''과 같은 항상 참인 조건을 넣으면 쿼리의 조건이 무조건 참이 되어 DB를 마음대로 조작하거나 인증을 우회할 수 있습니다 (lines 25). 다른 선택지들은 문서에서 설명한 행위와 맞지 않습니다.

1. 오답: 문서에는 해당 구문이 암호화와 관련 있다는 언급이 없습니다.
2. 오답: 문서에는 OR 구문이 쿼리 실행을 멈춘다고 설명하지 않습니다.
3. 정답: 문서에 기술된 방식으로, 항상 참이 되는 조건을 추가하여 무조건 적용되게 만든다고 설명되어 있습니다 (line 25).
4. 오답: 문서에는 OR 구문이 새로운 계정 생성과 관련된다고 언급하지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/SQL%20Injection.md',now(),'{"slot": 19, "topic": "인증 우회 기법", "learningObjective": "WHERE 절 변조로 인증을 우회하는 공격의 기본 메커니즘을 비교할 수 있습니다", "difficulty": "MEDIUM", "question": "공격자가 로그인 WHERE 절에 OR 문과 ''1'' = ''1'' 같은 구문을 추가하여 인증을 우회하는 이유로 가장 적절한 설명은 무엇입니까?", "options": ["해당 구문은 비밀번호를 암호화된 형태로 변환하여 서버가 항상 일치로 판단하게 만듭니다.", "추가된 OR 구문은 쿼리 실행을 멈추게 하여 인증 로직을 우회합니다.", "원래 조건이 참이 아니더라도 추가한 true 조건 때문에 WHERE 절 전체가 항상 참이 되어 인증 검사를 우회할 수 있기 때문입니다.", "OR ''1'' = ''1''은 데이터베이스에 새로운 계정을 자동으로 생성하기 때문에 인증이 우회됩니다."], "correctAnswer": 3, "explanation": "문서에서 설명하듯이 WHERE 절에 OR문을 추가하여 ''1'' = ''1''과 같은 항상 참인 조건을 넣으면 쿼리의 조건이 무조건 참이 되어 DB를 마음대로 조작하거나 인증을 우회할 수 있습니다 (lines 25). 다른 선택지들은 문서에서 설명한 행위와 맞지 않습니다.", "optionExplanations": ["오답: 문서에는 해당 구문이 암호화와 관련 있다는 언급이 없습니다.", "오답: 문서에는 OR 구문이 쿼리 실행을 멈춘다고 설명하지 않습니다.", "정답: 문서에 기술된 방식으로, 항상 참이 되는 조건을 추가하여 무조건 적용되게 만든다고 설명되어 있습니다 (line 25).", "오답: 문서에는 OR 구문이 새로운 계정 생성과 관련된다고 언급하지 않습니다."], "keywords": ["인증 우회", "WHERE 절", "OR ''1'' = ''1''"], "sourceEvidence": {"section": "Computer Science/Database/SQL Injection.md", "startLine": 25, "endLine": 25, "quote": "이 밖에도 기본 쿼리문의 WHERE 절에 OR문을 추가하여 `''1'' = ''1''`과 같은 true문을 작성하여 무조건 적용되도록 수정한 뒤 DB를 마음대로 조작할 수도 있다."}, "category": "DATABASE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Database/SQL Injection.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/SQL%20Injection.md", "id": "46169513-ee6f-5e35-975d-82113c6ee4ed", "review": {"blind": {"slot": 19, "correctOptionText": "원래 조건이 참이 아니더라도 추가한 true 조건 때문에 WHERE 절 전체가 항상 참이 되어 인증 검사를 우회할 수 있기 때문입니다.", "unambiguous": true, "reason": "문서에서 OR과 ''1'' = ''1''을 추가해 WHERE 절을 항상 참으로 만들어 우회한다고 설명한다.", "position": 3}, "evidenceAudit": {"slot": 19, "passed": true, "reason": "정답(3)은 원문에 명시된 WHERE 절에 항상 참인 조건을 추가해 인증을 우회한다는 설명과 일치합니다. 다른 선택지들은 원문에 근거가 없어 오답으로 판정됩니다. 난이도(MEDIUM)와 학습 목표도 적절합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:0c443dc58c4b1d14b47225263d90f482097cdc19981f7dc1474aa29aa127c49d"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('b824c794-d5e1-5a10-b700-4b6be4516215','46169513-ee6f-5e35-975d-82113c6ee4ed',1,'해당 구문은 비밀번호를 암호화된 형태로 변환하여 서버가 항상 일치로 판단하게 만듭니다.',false) ON CONFLICT DO NOTHING;
