INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('321be375-19b7-5d3e-abc5-dbea0eed8c20','46169513-ee6f-5e35-975d-82113c6ee4ed',4,'OR ''1'' = ''1''은 데이터베이스에 새로운 계정을 자동으로 생성하기 때문에 인증이 우회됩니다.',false) ON CONFLICT DO NOTHING;
