INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('8a9941c2-7b10-50c1-aa01-a8512092795f','c12baf2c-0380-5082-8ff4-90fe70b38912',3,'snapshot은 특정 지점을 디스크에 백업하고, AOF는 명령들을 저장해 재실행한다',true) ON CONFLICT DO NOTHING;
