INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('d221697a-7f6f-5f97-849a-003048feb7c3','d221697a-7f6f-5f97-849a-003048feb7c3',1,'다음 중 문서에서 ''Index 사용을 피해야 하는 경우''로 명시된 항목은 무엇입니까?','DATABASE','MEDIUM','CURATED','READY','문서의 ''Index 사용을 피해야 하는 경우'' 항목에서 (1) Data 중복도가 높은 Column과 (2) DML이 자주 일어나는 Column을 명시하고 있습니다. 따라서 중복도 높거나 DML이 빈번한 컬럼에는 인덱스를 피해야 합니다.

1. 틀렸습니다. Where 절에서 자주 사용되는 컬럼은 오히려 ''사용하면 좋은 경우''로 분류되어 있습니다.
2. 틀렸습니다. 외래키가 사용되는 컬럼은 ''사용하면 좋은 경우''에 포함되어 있습니다.
3. 틀렸습니다. Join에 자주 사용되는 컬럼도 ''사용하면 좋은 경우''로 분류되어 있습니다.
4. 정답입니다. 본문은 명시적으로 데이터 중복도가 높거나 DML이 자주 일어나는 컬럼에는 인덱스 사용을 피하라고 안내합니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/%5BDB%5D%20Index.md',now(),'{"slot": 28, "topic": "인덱스 사용 권장/비권장 판단", "learningObjective": "컬럼 특성(중복도, DML 빈도)에 따라 인덱스 사용을 피해야 하는 경우를 판단할 수 있다.", "difficulty": "MEDIUM", "question": "다음 중 문서에서 ''Index 사용을 피해야 하는 경우''로 명시된 항목은 무엇입니까?", "options": ["Where 절에서 자주 사용되는 컬럼", "외래키가 사용되는 컬럼", "Join에 자주 사용되는 컬럼", "데이터 중복도가 높은 컬럼 또는 DML이 자주 일어나는 컬럼"], "correctAnswer": 4, "explanation": "문서의 ''Index 사용을 피해야 하는 경우'' 항목에서 (1) Data 중복도가 높은 Column과 (2) DML이 자주 일어나는 Column을 명시하고 있습니다. 따라서 중복도 높거나 DML이 빈번한 컬럼에는 인덱스를 피해야 합니다.", "optionExplanations": ["틀렸습니다. Where 절에서 자주 사용되는 컬럼은 오히려 ''사용하면 좋은 경우''로 분류되어 있습니다.", "틀렸습니다. 외래키가 사용되는 컬럼은 ''사용하면 좋은 경우''에 포함되어 있습니다.", "틀렸습니다. Join에 자주 사용되는 컬럼도 ''사용하면 좋은 경우''로 분류되어 있습니다.", "정답입니다. 본문은 명시적으로 데이터 중복도가 높거나 DML이 자주 일어나는 컬럼에는 인덱스 사용을 피하라고 안내합니다."], "keywords": ["인덱스 회피 조건", "중복도", "DML 빈도"], "sourceEvidence": {"section": "Index(인덱스)", "startLine": 56, "endLine": 61, "quote": "- ##### Index 사용을 피해야 하는 경우\n\n  (1) Data 중복도가 높은 Column\n\n  (2) DML이 자주 일어나는 Column"}, "category": "DATABASE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Database/[DB] Index.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/%5BDB%5D%20Index.md", "id": "d221697a-7f6f-5f97-849a-003048feb7c3", "review": {"blind": {"slot": 28, "correctOptionText": "데이터 중복도가 높은 컬럼 또는 DML이 자주 일어나는 컬럼", "unambiguous": true, "reason": "문서의 ''Index 사용을 피해야 하는 경우''로 정확히 이 두 항목을 명시하고 있음.", "position": 4}, "evidenceAudit": {"slot": 28, "passed": true, "reason": "정답(옵션 4)은 소스의 ''Index 사용을 피해야 하는 경우'' 항목(데이터 중복도가 높은 컬럼, DML이 자주 일어나는 컬럼)을 정확히 담고 있으며 다른 선택지는 소스의 ''사용하면 좋은 경우''에 해당합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:2a0617e6e37c87086c8402ae0ef2f930a20551c914cd777480fe3bf33338de5c"}'::jsonb) ON CONFLICT DO NOTHING;
