INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('dd614896-9e86-5422-b0cb-4917c1a8858d','dd614896-9e86-5422-b0cb-4917c1a8858d',1,'문서에서 Redis의 value로 나열된 항목들 중 포함되지 않은 것은 무엇입니까?','DATABASE','MEDIUM','CURATED','READY','문서의 ''value 5가지'' 목록에는 String, set, sorted set, Hash, List가 포함되어 있습니다. Bitmap은 목록에 포함되어 있지 않습니다.

1. 문서에 List가 목록 항목으로 포함되어 있어 틀립니다.
2. 문서의 목록에 포함되어 있지 않습니다. 따라서 이 선택지는 정답입니다.
3. 문서에 "String (text, binary data) - 512MB까지 저장이 가능함"으로 명시되어 있어 틀립니다.
4. 문서에 Hash가 목록 항목으로 포함되어 있어 틀립니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/Redis.md',now(),'{"slot": 38, "topic": "Redis 자료구조", "learningObjective": "Redis가 지원하는 value 타입들을 나열하고 각 타입의 개념적 용도를 구분할 수 있다.", "difficulty": "MEDIUM", "question": "문서에서 Redis의 value로 나열된 항목들 중 포함되지 않은 것은 무엇입니까?", "options": ["List", "Bitmap", "String", "Hash"], "correctAnswer": 2, "explanation": "문서의 ''value 5가지'' 목록에는 String, set, sorted set, Hash, List가 포함되어 있습니다. Bitmap은 목록에 포함되어 있지 않습니다.", "optionExplanations": ["문서에 List가 목록 항목으로 포함되어 있어 틀립니다.", "문서의 목록에 포함되어 있지 않습니다. 따라서 이 선택지는 정답입니다.", "문서에 \"String (text, binary data) - 512MB까지 저장이 가능함\"으로 명시되어 있어 틀립니다.", "문서에 Hash가 목록 항목으로 포함되어 있어 틀립니다."], "keywords": ["value 타입", "String", "Hash", "List"], "sourceEvidence": {"section": "Redis", "quote": "value 5가지\n\n1. String (text, binary data) - 512MB까지 저장이 가능함\n2. set (String 집합)\n3. sorted set (set을 정렬해둔 상태)\n4. Hash\n5. List (양방향 연결리스트도 가능)"}, "category": "DATABASE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Database/Redis.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Database/Redis.md", "id": "dd614896-9e86-5422-b0cb-4917c1a8858d", "review": {"blind": {"slot": 38, "position": 2, "unambiguous": true, "reason": "문서에 나열된 값 유형은 String, set, sorted set, Hash, List이며 Bitmap은 포함되지 않음."}, "evidenceAudit": {"slot": 38, "passed": true, "reason": "Correct answer (Bitmap이 목록에 없음) is supported by the source list of five value types; the other options are explicitly listed in the source and thus provably incorrect as answers."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:850eb397c80e0695b1a23401978f2801d1f5322a79fb3708c578cfbef8115a73"}'::jsonb) ON CONFLICT DO NOTHING;
