INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('fa6fd5c2-faf8-5274-aa6b-a251452a40da','dd3de957-b155-50b3-90fd-4befd671c55a',3,'Redis의 String은 512MB 제한이 있어 700MB 파일은 직접 저장할 수 없으므로 다른 저장소를 사용하거나 파일을 분할해야 합니다.',true) ON CONFLICT DO NOTHING;
