INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('86b7adc9-6fe5-5ef5-abb2-02c2c114caff','7d21bb9f-1101-5086-a6b9-8c89d3aa9cf4',3,'FROM EX_TABLE CROSS JOIN NONE',false) ON CONFLICT DO NOTHING;
