INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('26f80a4c-b15d-51ef-8272-f3333cc63e1a','1','gyoogle','doc:gyoogle:23ebbb20f315bc0264c8c7752e13125b69cce42b944130033605c196ad61c710','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:23b1a82b42b5f1cd6f9f2f82ac45fa0d71ad8553dc35ad8d75c303c5b47c761b','csas-gyoogle-bank-v1','Trie','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Trie.md','Computer Science/Data Structure/Trie.md#문제에서 Trie를 java로 구현한 코드','##### 문제에서 Trie를 java로 구현한 코드

```java
static class Trie {
    boolean end;
    boolean pass;
    Trie[] child;

    Trie() {
        end = false;
        pass = false;
        child = new Trie[10];
    }

    public boolean insert(String str, int idx) {

        //끝나는 단어 있으면 false 종료
        if(end) return false;

        //idx가 str만큼 왔을때
        if(idx == str.length()) {
            end = true;
            if(pass) return false; // 더 지나가는 단어 있으면 false 종료
            else return true;
        }
        //아직 안왔을 때
        else {
            int next = str.charAt(idx) - ''0'';
            if(child[next] == null) {
                child[next] = new Trie();
                pass = true;
            }
            return child[next].insert(str, idx+1);
        }

    }
}
```','data-structure','') ON CONFLICT DO NOTHING;
