INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('f9e35950-1a3c-5014-bc97-7c05d5a010ec','1','gyoogle','doc:gyoogle:9c5bd9532ba883ce04de33bcfb7900f1681762ff1b0f93d9cb8bf730bcfe140e','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:af6a7aab78f6b2355d77fe9afa42fefdb47e2046f9dccf5b734123815308eafd','csas-gyoogle-bank-v1','Hash','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Hash.md','Computer Science/Data Structure/Hash.md#충돌 문제 해결','##### 충돌 문제 해결

1. **체이닝** : 연결리스트로 노드를 계속 추가해나가는 방식
   (제한 없이 계속 연결 가능, but 메모리 문제)

2. **Open Addressing** : 해시 함수로 얻은 주소가 아닌 다른 주소에 데이터를 저장할 수 있도록 허용 (해당 키 값에 저장되어있으면 다음 주소에 저장)

3. **선형 탐사** : 정해진 고정 폭으로 옮겨 해시값의 중복을 피함
4. **제곱 탐사** : 정해진 고정 폭을 제곱수로 옮겨 해시값의 중복을 피함

<br>','data-structure','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-819abe043eac1786','gyoogle-819abe043eac1786','Stack & Queue','Stack & Queue','DATA_STRUCTURE','gyoogle: Stack & Queue') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('f50bc44d-27a0-58fd-a55f-66b811c3703b','f50bc44d-27a0-58fd-a55f-66b811c3703b',1,'제공된 자료에 따르면 원형 큐(circular queue)의 단점으로 옳은 것은 무엇입니까?','DATA_STRUCTURE','MEDIUM','CURATED','READY','문서에서 원형 큐의 단점으로 ''메모리 공간은 잘 활용하지만, 배열로 구현되어 있기 때문에 큐의 크기가 제한''된다고 명시하고 있으므로 배열 기반이므로 크기가 제한되는 것이 단점입니다 (라인 453-455).

1. 오답: 문서에는 원형 큐가 ''메모리 공간은 잘 활용''한다고 긍정적으로 기술되어 있으므로 메모리 활용이 나쁘다는 설명은 문서와 반대입니다 (라인 452-453).
2. 오답: 문서에는 원형 큐가 인덱스를 (index + 1) % size로 순환시키므로 요소를 이동시키지 않는다고 설명되어 있으며, 매번 이동해야 한다고 나와 있지 않습니다 (라인 369-371, 399-401, 419-421).
3. 정답: 문서에 원형 큐의 단점으로 ''배열로 구현되어 있기 때문에 큐의 크기가 제한''된다고 직접 서술되어 있습니다 (라인 453-455).
4. 오답: 문서에는 원형 큐가 ''자리 하나를 항상 비워둠''으로 공백/포화 상태를 구분한다고 설명되어 있으며, 이로 인해 데이터 순환이 불가능하다는 주장은 문서에 없습니다(라인 366-371).','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Stack%20%26%20Queue.md',now(),'{"slot": 11, "topic": "원형 큐의 단점 비교", "learningObjective": "원형 큐와 일반 큐의 단점을 비교하여 원형 큐의 한계를 설명할 수 있습니다.", "difficulty": "MEDIUM", "question": "제공된 자료에 따르면 원형 큐(circular queue)의 단점으로 옳은 것은 무엇입니까?", "options": ["메모리 활용이 나빠서 빈 공간이 많이 생긴다.", "dequeue 시마다 배열의 모든 요소를 한 칸씩 이동해야 한다.", "배열로 구현되어 있기 때문에 큐의 크기가 제한된다.", "항상 하나의 빈 자리를 유지해야 해서 데이터 순환이 불가능하다."], "correctAnswer": 3, "explanation": "문서에서 원형 큐의 단점으로 ''메모리 공간은 잘 활용하지만, 배열로 구현되어 있기 때문에 큐의 크기가 제한''된다고 명시하고 있으므로 배열 기반이므로 크기가 제한되는 것이 단점입니다 (라인 453-455).", "optionExplanations": ["오답: 문서에는 원형 큐가 ''메모리 공간은 잘 활용''한다고 긍정적으로 기술되어 있으므로 메모리 활용이 나쁘다는 설명은 문서와 반대입니다 (라인 452-453).", "오답: 문서에는 원형 큐가 인덱스를 (index + 1) % size로 순환시키므로 요소를 이동시키지 않는다고 설명되어 있으며, 매번 이동해야 한다고 나와 있지 않습니다 (라인 369-371, 399-401, 419-421).", "정답: 문서에 원형 큐의 단점으로 ''배열로 구현되어 있기 때문에 큐의 크기가 제한''된다고 직접 서술되어 있습니다 (라인 453-455).", "오답: 문서에는 원형 큐가 ''자리 하나를 항상 비워둠''으로 공백/포화 상태를 구분한다고 설명되어 있으며, 이로 인해 데이터 순환이 불가능하다는 주장은 문서에 없습니다(라인 366-371)."], "keywords": ["원형 큐", "단점", "배열 기반", "크기 제한"], "sourceEvidence": {"section": "큐(Queue)", "startLine": 452, "endLine": 455, "quote": "원형 큐의 단점 : 메모리 공간은 잘 활용하지만, 배열로 구현되어 있기 때문에 큐의 크기가 제한\n\n<br>"}, "category": "DATA_STRUCTURE", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Data Structure/Stack & Queue.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Stack%20%26%20Queue.md", "id": "f50bc44d-27a0-58fd-a55f-66b811c3703b", "review": {"blind": {"slot": 11, "correctOptionText": "배열로 구현되어 있기 때문에 큐의 크기가 제한된다.", "unambiguous": true, "reason": "Source states the circular queue''s drawback is that, although it uses memory well, being array-based means the queue size is limited.", "position": 3}, "evidenceAudit": {"slot": 11, "passed": true, "reason": "The source explicitly lists the circular queue''s drawback: ''배열로 구현되어 있기 때문에 큐의 크기가 제한'' (i.e., array-based so size is limited), and the other options contradict or are not stated in the source."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:819abe043eac17867c1c5d70976020d50cbce4f0e2fd63e6698372ce385b6ef4"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('417d0c33-9dfe-57fc-915e-64bd6ce42b45','f50bc44d-27a0-58fd-a55f-66b811c3703b',1,'메모리 활용이 나빠서 빈 공간이 많이 생긴다.',false) ON CONFLICT DO NOTHING;
