INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('234f96b2-01e7-53f5-83b2-972be9660916','1','gyoogle','doc:gyoogle:5f6c19502a2e4bfdaa0734e271132e5627758ca97906b329d9564780d8b2be22','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:08921f89796562cdf7fe2bff7ee491e3b09ed555fc08be0d3777a0dc5b5e667f','csas-gyoogle-bank-v1','Heap','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Heap.md','Computer Science/Data Structure/Heap.md#언제 사용?','##### 언제 사용?

