INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('fd7bff38-15e3-5f07-a2bd-7d62bfa75e61','62e40e4d-ae57-5322-a38c-212518cb2dcb',3,'B+Tree는 leaf 노드들이 연결되지 않아 범위 탐색에 불리합니다.',false) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('f566049e-e5db-596d-a71e-43fbed6bc973','62e40e4d-ae57-5322-a38c-212518cb2dcb',4,'B+Tree는 내부 노드에는 key만 저장하고 데이터는 모두 leaf 노드에만 존재합니다.',true) ON CONFLICT DO NOTHING;
