INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('51029109-4d4d-5d98-b055-6f01d1c7c613','1','gyoogle','doc:gyoogle:e9eabab2285d974a17bdc3cfff9c5ca3c29cb8c85a6907b99388a101198f2f74','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:be4a89b5873a3fbc23bd805b194c48a64419f83fa9828a0f6fe5776a74d29312','csas-gyoogle-bank-v1','Binary Search Tree','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Data%20Structure/Binary%20Search%20Tree.md','Computer Science/Data Structure/Binary Search Tree.md#시간 복잡도','#### 시간 복잡도

