INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-3289e85580f1f961','gyoogle-3289e85580f1f961','TCP 3 way handshake & 4 way handshake','TCP 3 way handshake & 4 way handshake','NETWORK','gyoogle: TCP 3 way handshake & 4 way handshake') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('fef53546-b815-5854-b608-0a50e1fb9b58','fef53546-b815-5854-b608-0a50e1fb9b58',1,'3-way handshake 과정에서 클라이언트와 서버가 주고받는 세 가지 패킷의 올바른 순서는 무엇입니까?','NETWORK','EASY','CURATED','READY','문서에서는 먼저 클라이언트가 SYN을 보내고(라인 13), 서버가 SYN을 받고 ACK와 SYN을 보낸다고 하며(라인 15), 마지막으로 클라이언트가 ACK를 보낸다고 명시하고 있습니다(라인 17). 따라서 올바른 순서는 SYN → SYN+ACK → ACK입니다.

1. 정답입니다. 문서에 제시된 순서(클라이언트 SYN → 서버 SYN+ACK → 클라이언트 ACK)와 일치합니다 (라인 13, 15, 17).
2. 잘못된 순서입니다. 문서에서 ACK가 먼저 온다고 하지 않으며, 초기 메시지는 클라이언트의 SYN입니다 (라인 13).
3. 잘못된 순서입니다. 문서의 흐름과 일치하지 않습니다; 클라이언트가 최초로 보내는 것은 SYN입니다 (라인 13).
4. 잘못된 선택입니다. FIN/ACK는 연결 해제 절차에 해당하며, 3-way handshake에는 해당되지 않습니다 (라인 27, 33).','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/TCP%203%20way%20handshake%20%26%204%20way%20handshake.md',now(),'{"slot": 9, "topic": "TCP 3-way handshake 기본 흐름", "learningObjective": "클라이언트와 서버가 3-way handshake에서 주고받는 패킷의 순서를 설명할 수 있다", "difficulty": "EASY", "question": "3-way handshake 과정에서 클라이언트와 서버가 주고받는 세 가지 패킷의 올바른 순서는 무엇입니까?", "options": ["클라이언트가 SYN, 서버가 SYN+ACK, 클라이언트가 ACK", "클라이언트가 ACK, 서버가 SYN, 클라이언트가 SYN+ACK", "클라이언트가 SYN+ACK, 서버가 ACK, 클라이언트가 SYN", "클라이언트가 FIN, 서버가 ACK, 클라이언트가 ACK"], "correctAnswer": 1, "explanation": "문서에서는 먼저 클라이언트가 SYN을 보내고(라인 13), 서버가 SYN을 받고 ACK와 SYN을 보낸다고 하며(라인 15), 마지막으로 클라이언트가 ACK를 보낸다고 명시하고 있습니다(라인 17). 따라서 올바른 순서는 SYN → SYN+ACK → ACK입니다.", "optionExplanations": ["정답입니다. 문서에 제시된 순서(클라이언트 SYN → 서버 SYN+ACK → 클라이언트 ACK)와 일치합니다 (라인 13, 15, 17).", "잘못된 순서입니다. 문서에서 ACK가 먼저 온다고 하지 않으며, 초기 메시지는 클라이언트의 SYN입니다 (라인 13).", "잘못된 순서입니다. 문서의 흐름과 일치하지 않습니다; 클라이언트가 최초로 보내는 것은 SYN입니다 (라인 13).", "잘못된 선택입니다. FIN/ACK는 연결 해제 절차에 해당하며, 3-way handshake에는 해당되지 않습니다 (라인 27, 33)."], "keywords": ["3 way handshake", "SYN", "SYN+ACK", "ACK"], "sourceEvidence": {"section": "source file", "startLine": 13, "endLine": 17, "quote": "1) 클라이언트가 서버에게 SYN 패킷을 보냄 (sequence : x)\n\n2) 서버가 SYN(x)을 받고, 클라이언트로 받았다는 신호인 ACK와 SYN 패킷을 보냄 (sequence : y, ACK : x + 1)\n\n3) 클라이언트는 서버의 응답은 ACK(x+1)와 SYN(y) 패킷을 받고, ACK(y+1)를 서버로 보냄"}, "category": "NETWORK", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Network/TCP 3 way handshake & 4 way handshake.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/TCP%203%20way%20handshake%20%26%204%20way%20handshake.md", "id": "fef53546-b815-5854-b608-0a50e1fb9b58", "review": {"blind": {"slot": 9, "correctOptionText": "클라이언트가 SYN, 서버가 SYN+ACK, 클라이언트가 ACK", "unambiguous": true, "reason": "문서에 3-way handshake가 클라이언트 SYN → 서버 SYN+ACK → 클라이언트 ACK 순으로 설명되어 있음.", "position": 1}, "evidenceAudit": {"slot": 9, "passed": true, "reason": "정답(클라이언트 SYN → 서버 SYN+ACK → 클라이언트 ACK)이 출처(라인 13–17)에 명확히 제시되어 있으며, 다른 선택지는 출처와 일치하지 않아 모두 틀림."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:3289e85580f1f9616bdfa30ca5dcaa861afd2315e1ff924e8d2e32fa38e66074"}'::jsonb) ON CONFLICT DO NOTHING;
