INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('0676ef43-9439-5351-9fb2-7e1da4be84f8','1','gyoogle','doc:gyoogle:0433a69be43338271ebcfff687074daa3323e5639bf8b6d131b062109be9f14e','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:a92d8834b968ed7c39f18b419302cb8f7026e239c7b0ce916d7f82b36ff39f63','csas-gyoogle-bank-v1','DNS','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/DNS.md','Computer Science/Network/DNS.md#DNS (Domain Name Server)','# DNS (Domain Name Server)

모든 통신은 IP를 기반으로 연결된다. 하지만 사용자에게 일일히 IP 주소를 입력하기란 UX적으로 좋지 않다

때문에 DNS 가 등장 했으며 DNS 는 IP 주소와 도메인 주소를 매핑하는 역할을 수행한다','network','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-ea19a1973d2ab900','gyoogle-ea19a1973d2ab900','TCP (흐름제어혼잡제어)','TCP (흐름제어혼잡제어)','NETWORK','gyoogle: TCP (흐름제어혼잡제어)') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('9a4f7bdc-3b2a-57dd-a20d-98d382a32080','9a4f7bdc-3b2a-57dd-a20d-98d382a32080',1,'Stop and Wait 방식의 기본 동작은 무엇입니까?','NETWORK','EASY','CURATED','READY','본문은 Stop and Wait을 ''매번 전송한 패킷에 대해 확인 응답을 받아야만 그 다음 패킷을 전송하는 방법''이라고 설명합니다(라인 49). 따라서 각 패킷 전송 후 ACK를 받은 뒤 다음을 전송하는 방식이 맞습니다.

1. 오답: 여러 패킷을 연속 전송하는 것은 Sliding Window 계열의 동작으로 본문에 Sliding Window로 설명되어 있습니다(53-56, 65).
2. 오답: ''ACK가 세 번 중복되면 재전송''은 Fast Retransmit에 관한 설명이며 Stop and Wait의 동작이 아닙니다(109-114).
3. 오답: 송/수 신속도 조절을 곱셈·선형으로 하는 설명은 AIMD 또는 Fast Recovery 관련 내용이며 Stop and Wait과 무관합니다(98-101, 114-116).
4. 정답: 본문에 Stop and Wait은 매번 전송한 패킷에 대해 확인 응답을 받아야만 다음 패킷을 전송한다고 명시되어 있습니다(49).','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/TCP%20%28%ED%9D%90%EB%A6%84%EC%A0%9C%EC%96%B4%ED%98%BC%EC%9E%A1%EC%A0%9C%EC%96%B4%29.md',now(),'{"slot": 12, "topic": "Stop and Wait", "learningObjective": "Stop and Wait의 기본 동작을 설명할 수 있다", "difficulty": "EASY", "question": "Stop and Wait 방식의 기본 동작은 무엇입니까?", "options": ["여러 패킷을 윈도우 크기만큼 연속 전송하고 ACK를 모두 받은 뒤 윈도우를 옆으로 이동합니다.", "ACK가 세 번 중복되면 즉시 패킷을 재전송하고 윈도우 크기를 반으로 줄입니다.", "송신측과 수신측이 모두 전송 속도를 곱셈으로 줄였다가 선형으로 증가시키는 방식입니다.", "각 패킷을 보낸 뒤 그 패킷에 대한 확인 응답(ACK)을 받은 뒤에야 다음 패킷을 전송합니다."], "correctAnswer": 4, "explanation": "본문은 Stop and Wait을 ''매번 전송한 패킷에 대해 확인 응답을 받아야만 그 다음 패킷을 전송하는 방법''이라고 설명합니다(라인 49). 따라서 각 패킷 전송 후 ACK를 받은 뒤 다음을 전송하는 방식이 맞습니다.", "optionExplanations": ["오답: 여러 패킷을 연속 전송하는 것은 Sliding Window 계열의 동작으로 본문에 Sliding Window로 설명되어 있습니다(53-56, 65).", "오답: ''ACK가 세 번 중복되면 재전송''은 Fast Retransmit에 관한 설명이며 Stop and Wait의 동작이 아닙니다(109-114).", "오답: 송/수 신속도 조절을 곱셈·선형으로 하는 설명은 AIMD 또는 Fast Recovery 관련 내용이며 Stop and Wait과 무관합니다(98-101, 114-116).", "정답: 본문에 Stop and Wait은 매번 전송한 패킷에 대해 확인 응답을 받아야만 다음 패킷을 전송한다고 명시되어 있습니다(49)."], "keywords": ["Stop and Wait", "확인 응답", "흐름제어"], "sourceEvidence": {"section": "Computer Science/Network/TCP (흐름제어혼잡제어).md", "startLine": 49, "endLine": 49, "quote": "- Stop and Wait : 매번 전송한 패킷에 대해 확인 응답을 받아야만 그 다음 패킷을 전송하는 방법"}, "category": "NETWORK", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Network/TCP (흐름제어혼잡제어).md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/TCP%20%28%ED%9D%90%EB%A6%84%EC%A0%9C%EC%96%B4%ED%98%BC%EC%9E%A1%EC%A0%9C%EC%96%B4%29.md", "id": "9a4f7bdc-3b2a-57dd-a20d-98d382a32080", "review": {"blind": {"slot": 12, "correctOptionText": "각 패킷을 보낸 뒤 그 패킷에 대한 확인 응답(ACK)을 받은 뒤에야 다음 패킷을 전송합니다.", "unambiguous": true, "reason": "본문의 Stop and Wait 정의는 매번 전송한 패킷에 대해 ACK를 받아야만 다음 패킷을 전송한다고 설명하고 있음.", "position": 4}, "evidenceAudit": {"slot": 12, "passed": true, "reason": "Correct answer (옵션 4) matches the source line 49 exactly; other options describe Sliding Window, Fast Retransmit, or AIMD behavior which the source assigns elsewhere, so they are provably wrong for Stop-and-Wait."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:ea19a1973d2ab900acdf329f74d303ef0e7797bae41015440b5e88f6563d68ab"}'::jsonb) ON CONFLICT DO NOTHING;
