INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('585f0cb7-5978-59df-936a-183aabc86218','1','gyoogle','doc:gyoogle:78f72017a11e53d66db8e94c38fb45170aa914d777fc505574bf7472192d5a6d','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:18739536b013c5eef21cec4029928b70fc7c562f5747c3e22f3c260d724ab7e4','csas-gyoogle-bank-v1','로드 밸런싱(Load Balancing)','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/%EB%A1%9C%EB%93%9C%20%EB%B0%B8%EB%9F%B0%EC%8B%B1%28Load%20Balancing%29.md','Computer Science/Network/로드 밸런싱(Load Balancing).md#로드 밸런서가 서버를 선택하는 방식','#### 로드 밸런서가 서버를 선택하는 방식

- 라운드 로빈(Round Robin) : CPU 스케줄링의 라운드 로빈 방식 활용
- Least Connections : 연결 개수가 가장 적은 서버 선택 (트래픽으로 인해 세션이 길어지는 경우 권장)
- Source : 사용자 IP를 해싱하여 분배 (특정 사용자가 항상 같은 서버로 연결되는 것 보장)

<br>','network','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-107af74aa3b0e568','gyoogle-107af74aa3b0e568','[Network] Blocking Non-Blocking IO','[Network] Blocking Non-Blocking IO','NETWORK','gyoogle: [Network] Blocking Non-Blocking IO') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('1baa6d8d-2c6d-528c-a0f1-5b9ce311a193','1baa6d8d-2c6d-528c-a0f1-5b9ce311a193',1,'Non-Blocking I/O 환경에서 recvfrom을 호출했을 때 커널이 EWOULDBLOCK을 반환하면 사용자 프로세스는 어떤 행동을 취할 수 있습니까?','NETWORK','MEDIUM','CURATED','READY','본문은 Non-Blocking I/O에서 커널이 recvfrom에 대해 EWOULDBLOCK을 반환할 때, Blocking 방식과 달리 사용자 프로세스는 다른 작업을 진행할 수 있다고 명시합니다. 따라서 EWOULDBLOCK은 즉시 대기하지 않고 계속 실행할 수 있음을 의미합니다.

1. 오답: 본문은 블록 상태로 전환된다고 설명하지 않으며, 오히려 블록하지 않는 동작을 강조합니다.
2. 정답: 소스는 EWOULDBLOCK을 반환해도 사용자 프로세스가 다른 작업을 수행할 수 있다고 분명히 기술합니다. (lines 37-41)
3. 오답: 본문은 프로세스가 종료되어야 한다고 말하지 않습니다; 종료는 적절하지 않습니다.
4. 오답: 본문은 커널에게 강제 전송 요청을 해야 한다고 언급하지 않습니다; EWOULDBLOCK은 단순히 데이터가 아직 없음을 알립니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/%5BNetwork%5D%20Blocking%20Non-Blocking%20IO.md',now(),'{"slot": 18, "topic": "Non-Blocking I/O 동작 순서", "learningObjective": "recvfrom 호출이 Non-Blocking 모드에서 EWOULDBLOCK을 반환하는 의미와 이후 프로세스의 동작을 설명할 수 있습니다", "difficulty": "MEDIUM", "question": "Non-Blocking I/O 환경에서 recvfrom을 호출했을 때 커널이 EWOULDBLOCK을 반환하면 사용자 프로세스는 어떤 행동을 취할 수 있습니까?", "options": ["프로세스는 즉시 블록 상태로 전환되어 다른 스레드가 데이터 수신을 대체해야 합니다.", "해당 프로세스는 I/O를 기다리며 중단하지 않고 다른 작업을 계속 수행할 수 있습니다.", "프로세스는 즉시 종료되어야 하며, 나중에 재시작해야 합니다.", "프로세스는 커널에게 강제로 데이터를 즉시 전송하도록 요청해야 합니다."], "correctAnswer": 2, "explanation": "본문은 Non-Blocking I/O에서 커널이 recvfrom에 대해 EWOULDBLOCK을 반환할 때, Blocking 방식과 달리 사용자 프로세스는 다른 작업을 진행할 수 있다고 명시합니다. 따라서 EWOULDBLOCK은 즉시 대기하지 않고 계속 실행할 수 있음을 의미합니다.", "optionExplanations": ["오답: 본문은 블록 상태로 전환된다고 설명하지 않으며, 오히려 블록하지 않는 동작을 강조합니다.", "정답: 소스는 EWOULDBLOCK을 반환해도 사용자 프로세스가 다른 작업을 수행할 수 있다고 분명히 기술합니다. (lines 37-41)", "오답: 본문은 프로세스가 종료되어야 한다고 말하지 않습니다; 종료는 적절하지 않습니다.", "오답: 본문은 커널에게 강제 전송 요청을 해야 한다고 언급하지 않습니다; EWOULDBLOCK은 단순히 데이터가 아직 없음을 알립니다."], "keywords": ["Non-Blocking", "EWOULDBLOCK", "recvfrom"], "sourceEvidence": {"section": "Blocking I/O & Non-Blocking I/O.md", "startLine": 35, "endLine": 43, "quote": "* 진행 순서\n\n     1. User Process가 recvfrom 함수 호출 (커널에게 해당 Socket으로부터 data를 받고 싶다고 요청함)\n\n     2. Kernel은 이 요청에 대해서, 곧바로 recvBuffer를 채워서 보내지 못하므로, \"EWOULDBLOCK\"을 return함.\n\n     3. Blocking 방식과 달리, User Process는 다른 작업을 진행할 수 있음.\n\n     4. recvBuffer에 user가 받을 수 있는 데이터가 있는 경우, Buffer로부터 데이터를 복사하여 받아옴."}, "category": "NETWORK", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Network/[Network] Blocking Non-Blocking IO.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/%5BNetwork%5D%20Blocking%20Non-Blocking%20IO.md", "id": "1baa6d8d-2c6d-528c-a0f1-5b9ce311a193", "review": {"blind": {"slot": 18, "correctOptionText": "해당 프로세스는 I/O를 기다리며 중단하지 않고 다른 작업을 계속 수행할 수 있습니다.", "unambiguous": true, "reason": "본문은 Non-Blocking I/O에서 커널이 EWOULDBLOCK을 반환하면 사용자 프로세스가 다른 작업을 진행할 수 있다고 설명함.", "position": 2}, "evidenceAudit": {"slot": 18, "passed": true, "reason": "정답(2)은 본문이 EWOULDBLOCK 반환 시 ''사용자 프로세스는 다른 작업을 진행할 수 있음''이라 한 진술과 일치합니다. 나머지 선택지는 본문에 근거가 없습니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:107af74aa3b0e5681be5aa9f24a7752bb4dcae61472df402d9010c9304430037"}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('a54e2725-043b-5eae-a41a-2f5529e0e71b','1baa6d8d-2c6d-528c-a0f1-5b9ce311a193',1,'프로세스는 즉시 블록 상태로 전환되어 다른 스레드가 데이터 수신을 대체해야 합니다.',false) ON CONFLICT DO NOTHING;
