INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('54254f60-01fc-57ee-9302-71937947b8a6','54254f60-01fc-57ee-9302-71937947b8a6',1,'UDP 헤더에 포함된 항목 중 오류 검출을 담당하는 필드는 무엇입니까?','NETWORK','MEDIUM','CURATED','READY','문서의 UDP Header 설명에서 ''Checksum : 오류 검출''이라고 명확히 표기되어 있으며, 체크섬은 전송된 자료의 무결성 보호를 위한 중복 검사 형태라고 설명되어 있습니다.

1. Source port는 송신 측 포트 식별용으로, 오류 검출 기능과 관련이 없습니다.
2. Length는 데이터 길이를 나타내는 필드로 오류 검출 역할이 아닙니다.
3. Destination port는 수신 측 포트 식별용으로 오류 검출과 관련이 없습니다.
4. 정답입니다. 문서에 체크섬이 오류 검출용 필드라고 명시되어 있습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/UDP.md',now(),'{"slot": 24, "topic": "UDP 헤더 필드", "learningObjective": "UDP 헤더에 포함된 필드를 식별하고 그 기능을 설명할 수 있다.", "difficulty": "MEDIUM", "question": "UDP 헤더에 포함된 항목 중 오류 검출을 담당하는 필드는 무엇입니까?", "options": ["Source port 필드", "Length 필드", "Destination port 필드", "Checksum 필드"], "correctAnswer": 4, "explanation": "문서의 UDP Header 설명에서 ''Checksum : 오류 검출''이라고 명확히 표기되어 있으며, 체크섬은 전송된 자료의 무결성 보호를 위한 중복 검사 형태라고 설명되어 있습니다.", "optionExplanations": ["Source port는 송신 측 포트 식별용으로, 오류 검출 기능과 관련이 없습니다.", "Length는 데이터 길이를 나타내는 필드로 오류 검출 역할이 아닙니다.", "Destination port는 수신 측 포트 식별용으로 오류 검출과 관련이 없습니다.", "정답입니다. 문서에 체크섬이 오류 검출용 필드라고 명시되어 있습니다."], "keywords": ["Checksum", "오류 검출", "UDP Header"], "sourceEvidence": {"section": "UDP.md", "startLine": 46, "endLine": 51, "quote": "- <img src=''https://t1.daumcdn.net/cfile/tistory/272A5A385759267B36''>\n  - Source port : 시작 포트\n  - Destination port : 도착지 포트\n  - Length : 길이\n  - _Checksum_ : 오류 검출\n    - 중복 검사의 한 형태로, 오류 정정을 통해 공간이나 시간 속에서 송신된 자료의 무결성을 보호하는 단순한 방법이다."}, "category": "NETWORK", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Network/UDP.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/UDP.md", "id": "54254f60-01fc-57ee-9302-71937947b8a6", "review": {"blind": {"slot": 24, "correctOptionText": "Checksum 필드", "unambiguous": true, "reason": "문서의 UDP 헤더 설명에서 Checksum이 오류 검출을 담당한다고 명시됨.", "position": 4}, "evidenceAudit": {"slot": 24, "passed": true, "reason": "Source lists UDP header fields and labels ''Checksum : 오류 검출'', directly supporting option 4; other options are identified in the source as port/length fields without error-detection roles. Explanations and difficulty are consistent with the source."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:0ec186bcdb75a6cc3de3bc6da95a0b2edd548a74096aa7144e44fed4f2b0a73a"}'::jsonb) ON CONFLICT DO NOTHING;
