INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('a7482236-771c-5f84-be63-d6ea4a826a41','f13f514f-fc49-5137-a69d-b1ee7faf27e3',3,'서버의 공개키를 제공하여 클라이언트가 인증서 유효성을 CA 목록과 대조해 확인한다',true) ON CONFLICT DO NOTHING;
