INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('b229a191-de6f-5a7f-9f7d-e759471ce98c','f40b877e-872a-5e93-ac39-bb3fe86e8652',2,'루트·TLD·Authoritative 서버만 ‘네임서버’이고, 재귀적으로 요청을 보내는 클라이언트측 DNS는 아무 호칭도 갖지 않습니다.',false) ON CONFLICT DO NOTHING;
INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('ed222464-7946-5e53-a146-3057e01b7cc9','f40b877e-872a-5e93-ac39-bb3fe86e8652',3,'hosts 파일을 참조하는 로컬 파일이 ‘네임서버’ 역할을 하며, 네트워크로 요청을 보내는 쪽이 ‘DNS 리쿼서’가 아닙니다.',false) ON CONFLICT DO NOTHING;
