INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('3ac43ffa-db45-5e0f-8157-717934afae16','d31b206a-04dd-54a8-9dd2-77c147d09966',4,'대칭키는 최초부터 공개키 암호화로 전송되므로 중간자가 공개키를 알면 곧바로 대칭키를 얻기 때문입니다.',false) ON CONFLICT DO NOTHING;
