INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('7d93c58f-d501-5b92-9e1e-6c4badd4eb14','1','gyoogle','doc:gyoogle:78f72017a11e53d66db8e94c38fb45170aa914d777fc505574bf7472192d5a6d','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:18739536b013c5eef21cec4029928b70fc7c562f5747c3e22f3c260d724ab7e4','csas-gyoogle-bank-v1','로드 밸런싱(Load Balancing)','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Network/%EB%A1%9C%EB%93%9C%20%EB%B0%B8%EB%9F%B0%EC%8B%B1%28Load%20Balancing%29.md','Computer Science/Network/로드 밸런싱(Load Balancing).md#로드 밸런서가 서버를 선택하는 방식','#### 로드 밸런서가 서버를 선택하는 방식

- 라운드 로빈(Round Robin) : CPU 스케줄링의 라운드 로빈 방식 활용
- Least Connections : 연결 개수가 가장 적은 서버 선택 (트래픽으로 인해 세션이 길어지는 경우 권장)
- Source : 사용자 IP를 해싱하여 분배 (특정 사용자가 항상 같은 서버로 연결되는 것 보장)

<br>','network','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-c9a3aafe29b04a24','gyoogle-c9a3aafe29b04a24','Memory','Memory','OPERATING_SYSTEM','gyoogle: Memory') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('57feb983-0ed1-56c9-b5c8-aadf2aaae101','57feb983-0ed1-56c9-b5c8-aadf2aaae101',1,'메인 메모리(main memory)에 대해 옳은 설명은 무엇입니까?','OPERATING_SYSTEM','EASY','CURATED','READY','본문은 메인 메모리를 ''CPU가 직접 접근할 수 있는 기억 장치''라고 정의하고, ''프로세스가 실행되려면 프로그램이 메모리에 올라와야 함''을 명시하고 있습니다(라인 3–5). 따라서 옵션 1이 정답입니다.

1. 올바름: 파일의 처음 부분에서 메인 메모리를 CPU가 직접 접근하는 기억 장치로 정의하고, 프로그램이 실행되려면 메모리에 올라와야 한다고 설명합니다 (라인 3–5).
2. 오답: 본문에는 메인 메모리가 디스크처럼 영구 저장을 보장한다는 내용이 없습니다; 오히려 메인 메모리와 영구 저장 장치(디스크)의 구분이 문맥상 존재합니다 (관련 서술 없음).
3. 오답: 본문은 캐시와 메인 메모리의 상대적 속도 차이를 설명하지만, ''레지스터보다 더 빠르게 접근할 수 없도록''이라는 표현은 없습니다; 레지스터는 별도로 언급되어 있지 않습니다 (관련 서술 없음).
4. 오답: 메인 메모리는 데이터를 저장하고 CPU가 접근하는 기억 장치이지, CPU가 명령어를 생성하여 프로그램을 작성하는 장치는 아닙니다 (관련 서술 없음).','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Memory.md',now(),'{"slot": 1, "topic": "메인 메모리의 역할", "learningObjective": "메인 메모리가 CPU와 어떤 관계로 동작하는지 설명할 수 있습니다.", "difficulty": "EASY", "question": "메인 메모리(main memory)에 대해 옳은 설명은 무엇입니까?", "options": ["메인 메모리는 CPU가 직접 접근하는 기억 장치이며, 프로세스가 실행되려면 프로그램이 메모리에 올라와야 합니다.", "메인 메모리는 디스크처럼 영구 저장을 위해 설계되어, 전원이 꺼져도 데이터가 유지됩니다.", "메인 메모리는 캐시보다 느리지만 보통 레지스터보다 더 빠르게 접근할 수 없도록 설계됩니다.", "메인 메모리는 CPU가 직접 명령어를 생성하여 프로그램을 작성하는 장치입니다."], "correctAnswer": 1, "explanation": "본문은 메인 메모리를 ''CPU가 직접 접근할 수 있는 기억 장치''라고 정의하고, ''프로세스가 실행되려면 프로그램이 메모리에 올라와야 함''을 명시하고 있습니다(라인 3–5). 따라서 옵션 1이 정답입니다.", "optionExplanations": ["올바름: 파일의 처음 부분에서 메인 메모리를 CPU가 직접 접근하는 기억 장치로 정의하고, 프로그램이 실행되려면 메모리에 올라와야 한다고 설명합니다 (라인 3–5).", "오답: 본문에는 메인 메모리가 디스크처럼 영구 저장을 보장한다는 내용이 없습니다; 오히려 메인 메모리와 영구 저장 장치(디스크)의 구분이 문맥상 존재합니다 (관련 서술 없음).", "오답: 본문은 캐시와 메인 메모리의 상대적 속도 차이를 설명하지만, ''레지스터보다 더 빠르게 접근할 수 없도록''이라는 표현은 없습니다; 레지스터는 별도로 언급되어 있지 않습니다 (관련 서술 없음).", "오답: 메인 메모리는 데이터를 저장하고 CPU가 접근하는 기억 장치이지, CPU가 명령어를 생성하여 프로그램을 작성하는 장치는 아닙니다 (관련 서술 없음)."], "keywords": ["메인 메모리", "CPU 접근", "프로세스 실행"], "sourceEvidence": {"section": "Computer Science/Operating System/Memory.md", "startLine": 3, "endLine": 5, "quote": "> 메인 메모리는 CPU가 직접 접근할 수 있는 기억 장치\n>\n> 프로세스가 실행되려면 프로그램이 메모리에 올라와야 함"}, "category": "OPERATING_SYSTEM", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Operating System/Memory.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Memory.md", "id": "57feb983-0ed1-56c9-b5c8-aadf2aaae101", "review": {"blind": {"slot": 1, "correctOptionText": "메인 메모리는 CPU가 직접 접근하는 기억 장치이며, 프로세스가 실행되려면 프로그램이 메모리에 올라와야 합니다.", "unambiguous": true, "reason": "본문에서 메인 메모리는 CPU가 직접 접근할 수 있는 기억 장치이며 프로세스 실행을 위해 프로그램이 메모리에 올라와야 한다고 명시함.", "position": 1}, "evidenceAudit": {"slot": 1, "passed": true, "reason": "문항의 정답(옵션1)은 원문에서 직접적으로 명시되어 있으며(메인 메모리는 CPU가 직접 접근하는 기억 장치, 프로세스 실행 위해 프로그램이 메모리에 올라와야 함), 나머지 보기들은 원문에 근거가 없거나 반대되는 내용을 담아 정확히 오답임이 증명됩니다. 설명·난이도·학습목표·한국어 표현 모두 적절합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:c9a3aafe29b04a243d4005a3ae0701e3675bc0e930419f20a507e946eb797e16"}'::jsonb) ON CONFLICT DO NOTHING;
