INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('fdcee600-ecdd-58b5-be39-dae359b5c78f','fdcee600-ecdd-58b5-be39-dae359b5c78f',1,'wait() 시스템콜의 역할로 옳은 것은 무엇입니까?','OPERATING_SYSTEM','EASY','CURATED','READY','본문은 wait가 “child 프로세스가 종료될 때까지 기다리는 작업”이라고 분명히 설명합니다. 또한 wait()는 child가 끝나기 전에는 return하지 않으므로 부모가 자식의 종료를 기다리게 함을 명시하고 있습니다.

1. wait는 즉시 반환하여 백그라운드 전환시키는 기능이 아니라, 자식 종료까지 블록합니다.
2. 정답입니다. (입증 근거: wait는 부모가 자식의 종료를 기다리게 합니다.)
3. 자식이 부모를 기다린다는 설명은 본문에 없습니다; 실제로는 부모가 자식을 기다립니다.
4. wait는 새로운 프로세스를 생성하지 않습니다; 자식의 종료를 기다리는 동작입니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/%5BOS%5D%20System%20Call%20%28Fork%20Wait%20Exec%29.md',now(),'{"slot": 2, "topic": "wait 시스템콜의 기본 동작", "learningObjective": "wait 시스템콜이 부모 프로세스에 미치는 기본 동작을 설명할 수 있습니다.", "difficulty": "EASY", "question": "wait() 시스템콜의 역할로 옳은 것은 무엇입니까?", "options": ["자식 프로세스를 백그라운드로 전환하여 즉시 반환한다.", "부모 프로세스가 자식 프로세스의 종료를 기다리게 한다.", "자식 프로세스가 부모 프로세스의 종료를 기다리게 한다.", "새로운 프로세스를 생성하여 부모와 자식이 동시에 종료되도록 한다."], "correctAnswer": 2, "explanation": "본문은 wait가 “child 프로세스가 종료될 때까지 기다리는 작업”이라고 분명히 설명합니다. 또한 wait()는 child가 끝나기 전에는 return하지 않으므로 부모가 자식의 종료를 기다리게 함을 명시하고 있습니다.", "optionExplanations": ["wait는 즉시 반환하여 백그라운드 전환시키는 기능이 아니라, 자식 종료까지 블록합니다.", "정답입니다. (입증 근거: wait는 부모가 자식의 종료를 기다리게 합니다.)", "자식이 부모를 기다린다는 설명은 본문에 없습니다; 실제로는 부모가 자식을 기다립니다.", "wait는 새로운 프로세스를 생성하지 않습니다; 자식의 종료를 기다리는 동작입니다."], "keywords": ["wait", "부모", "자식", "종료 대기"], "sourceEvidence": {"section": "[Operating System] System Call", "startLine": 73, "endLine": 76, "quote": "##### wait\n\n> child 프로세스가 종료될 때까지 기다리는 작업"}, "category": "OPERATING_SYSTEM", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Operating System/[OS] System Call (Fork Wait Exec).md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/%5BOS%5D%20System%20Call%20%28Fork%20Wait%20Exec%29.md", "id": "fdcee600-ecdd-58b5-be39-dae359b5c78f", "review": {"blind": {"slot": 2, "correctOptionText": "부모 프로세스가 자식 프로세스의 종료를 기다리게 한다.", "unambiguous": true, "reason": "본문: ''wait는 Process (Parent)가 만든 다른 Process(child) 가 끝날 때까지 기다리는 명령어임.''", "position": 2}, "evidenceAudit": {"slot": 2, "passed": true, "reason": "질문, 정답(부모가 자식 종료 대기), 오답 해설 모두 출처의 ''wait는 child 프로세스가 종료될 때까지 기다리는 작업'' 설명과 일치함."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:4ae22c219df956bd6c8dfe69c585585a2ffdfa94e2f9864056f7d4f1e23bcc56"}'::jsonb) ON CONFLICT DO NOTHING;
