INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('b5832d30-7e91-5cbe-9852-3e33c249fbc8','b5832d30-7e91-5cbe-9852-3e33c249fbc8',1,'다음 중 ''Race Condition''의 가장 정확한 설명은 무엇입니까?','OPERATING_SYSTEM','EASY','CURATED','READY','문서에서는 공유 자원에 대해 여러 프로세스가 동시에 접근할 때 결과값에 영향을 줄 수 있는 상태를 Race Condition으로 정의하고, 동시 접근 시 자료의 일관성이 해치는 결과가 나타난다고 설명합니다. 나머지 보기들은 문서의 Race Condition 정의와 일치하지 않습니다.

1. 오답: 설명은 프로세스의 메모리 복사(예: fork 관련)와 관련되며 Race Condition 정의와 다릅니다.
2. 오답: CPU 사용률 문제에 대한 설명으로 문서의 Race Condition 정의와 관련이 없습니다.
3. 정답: 문서의 정의와 일치합니다(공유 자원에 대한 동시 접근이 결과에 영향을 줌).
4. 오답: 문서에서는 Race Condition을 동시 접근으로 인한 자료 불일치로 설명하며, 블로킹 상태만으로 Race Condition이라 하지 않습니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Race%20Condition.md',now(),'{"slot": 15, "topic": "Race Condition 정의", "learningObjective": "공유 자원에 대한 동시 접근이 어떤 상황을 Race Condition으로 분류되는지 식별할 수 있습니다.", "difficulty": "EASY", "question": "다음 중 ''Race Condition''의 가장 정확한 설명은 무엇입니까?", "options": ["하나의 프로세스가 다른 프로세스의 메모리를 완전히 복사하여 독립적으로 실행되는 상태입니다.", "프로세스가 입출력 장치의 데이터 전송 속도보다 빠르게 실행되어 CPU 사용률이 과도해지는 상태입니다.", "서로 다른 프로세스가 공유 자원에 동시에 접근하여 최종 결과가 달라질 수 있는 상태입니다.", "단일 프로세스가 블록된 I/O를 기다리는 동안 다른 프로세스가 CPU를 전혀 사용하지 못하게 되는 상태입니다."], "correctAnswer": 3, "explanation": "문서에서는 공유 자원에 대해 여러 프로세스가 동시에 접근할 때 결과값에 영향을 줄 수 있는 상태를 Race Condition으로 정의하고, 동시 접근 시 자료의 일관성이 해치는 결과가 나타난다고 설명합니다. 나머지 보기들은 문서의 Race Condition 정의와 일치하지 않습니다.", "optionExplanations": ["오답: 설명은 프로세스의 메모리 복사(예: fork 관련)와 관련되며 Race Condition 정의와 다릅니다.", "오답: CPU 사용률 문제에 대한 설명으로 문서의 Race Condition 정의와 관련이 없습니다.", "정답: 문서의 정의와 일치합니다(공유 자원에 대한 동시 접근이 결과에 영향을 줌).", "오답: 문서에서는 Race Condition을 동시 접근으로 인한 자료 불일치로 설명하며, 블로킹 상태만으로 Race Condition이라 하지 않습니다."], "keywords": ["공유 자원", "동시 접근", "자료 일관성"], "sourceEvidence": {"section": "Computer Science/Operating System/Race Condition.md", "startLine": 3, "endLine": 5, "quote": "공유 자원에 대해 여러 프로세스가 동시에 접근할 때, 결과값에 영향을 줄 수 있는 상태\n\n> 동시 접근 시 자료의 일관성을 해치는 결과가 나타남"}, "category": "OPERATING_SYSTEM", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Operating System/Race Condition.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Race%20Condition.md", "id": "b5832d30-7e91-5cbe-9852-3e33c249fbc8", "review": {"blind": {"slot": 15, "correctOptionText": "서로 다른 프로세스가 공유 자원에 동시에 접근하여 최종 결과가 달라질 수 있는 상태입니다.", "unambiguous": true, "reason": "Source defines Race Condition as multiple processes accessing a shared resource simultaneously causing differing results.", "position": 3}, "evidenceAudit": {"slot": 15, "passed": true, "reason": "정답(3)은 제공된 출처의 정의 문구와 정확히 일치하며, 나머지 보기들은 출처에 언급되지 않아 오답으로 판정 가능합니다. 설명·난이도·학습목표도 출처와 부합합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:2fbc1051ead9f0a9a1709f1c0e019fb641531ec2bb4b52cf892b3d298fda6fcf"}'::jsonb) ON CONFLICT DO NOTHING;
