INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('e8b88672-72c2-5726-971b-09dcef291a23','159ef1b0-228d-592a-a480-60ace7bf9922',4,'데이터 세그먼트',true) ON CONFLICT DO NOTHING;
