INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('5076c15a-6063-5a0f-9e50-b8ca2c81252c','1','gyoogle','doc:gyoogle:d4cf8e52978f1ca85178d39c6c73f38bc557116181b745495fa9feb0a4779c43','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:cc2c5570921441e4596cb0f491860fcad593744f635ee8e7091e1e6d05992cc8','csas-gyoogle-bank-v1','PCB & Context Switcing','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/PCB%20%26%20Context%20Switcing.md','Computer Science/Operating System/PCB & Context Switcing.md#PCB는 어떻게 관리되나요?','##### PCB는 어떻게 관리되나요?

> Linked List 방식으로 관리함
>
> PCB List Head에 PCB들이 생성될 때마다 붙게 된다. 주소값으로 연결이 이루어져 있는 연결리스트이기 때문에 삽입 삭제가 용이함.
>
> 즉, 프로세스가 생성되면 해당 PCB가 생성되고 프로세스 완료시 제거됨

<br>

<br>

이렇게 수행 중인 프로세스를 변경할 때, CPU의 레지스터 정보가 변경되는 것을 `Context Switching`이라고 한다.','operating-system','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-7b8eaf5910a19ef4','gyoogle-7b8eaf5910a19ef4','Process Management & PCB','Process Management & PCB','OPERATING_SYSTEM','gyoogle: Process Management & PCB') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('002a41c3-5351-5d3e-ad0a-fa438d616ada','002a41c3-5351-5d3e-ad0a-fa438d616ada',1,'문서에 따르면 PCB를 연결 리스트(Linked List)로 관리하는 주된 장점은 무엇입니까?','OPERATING_SYSTEM','MEDIUM','CURATED','READY','문서는 PCB를 Linked List 방식으로 관리하며 주소값 연결로 인해 ''삽입 삭제가 용이함''을 장점으로 명시합니다. 따라서 프로세스 생성 시 PCB를 붙이고 완료 시 제거하는 작업에 효율적입니다.

1. 오답: 문서에서는 연결 리스트가 메모리 접근 속도를 일정하게 하거나 실시간 보장을 제공한다고 언급하지 않았습니다.
2. 오답: 문서는 디스크 기반 정렬이나 검색 속도 향상에 대해 언급하지 않습니다; 연결 리스트는 일반적으로 검색이 빠르지 않습니다.
3. 오답: 문서에는 PCB가 고정된 메모리 오프셋을 가진다는 내용이나 캐시 최적화 관련 설명이 나오지 않습니다.
4. 정답: 소스는 ''주소값으로 연결이 이루어져 있는 연결리스트이기 때문에 삽입 삭제가 용이함''이라 직접 설명합니다.','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Process%20Management%20%26%20PCB.md',now(),'{"slot": 28, "topic": "PCB 관리 방식", "learningObjective": "PCB를 링크드 리스트로 관리하는 설계의 이점을 메커니즘 관점에서 비교할 수 있습니다.", "difficulty": "MEDIUM", "question": "문서에 따르면 PCB를 연결 리스트(Linked List)로 관리하는 주된 장점은 무엇입니까?", "options": ["메모리 접근 속도가 항상 일정하여 실시간 보장이 가능하다", "디스크 기반 정렬을 통해 대규모 프로세스 집합에서 검색이 빨라진다", "각 PCB가 고정된 메모리 오프셋을 가져 캐시 성능이 최적화된다", "삽입과 삭제가 용이하여 프로세스 생성·완료 시 효율적이다"], "correctAnswer": 4, "explanation": "문서는 PCB를 Linked List 방식으로 관리하며 주소값 연결로 인해 ''삽입 삭제가 용이함''을 장점으로 명시합니다. 따라서 프로세스 생성 시 PCB를 붙이고 완료 시 제거하는 작업에 효율적입니다.", "optionExplanations": ["오답: 문서에서는 연결 리스트가 메모리 접근 속도를 일정하게 하거나 실시간 보장을 제공한다고 언급하지 않았습니다.", "오답: 문서는 디스크 기반 정렬이나 검색 속도 향상에 대해 언급하지 않습니다; 연결 리스트는 일반적으로 검색이 빠르지 않습니다.", "오답: 문서에는 PCB가 고정된 메모리 오프셋을 가진다는 내용이나 캐시 최적화 관련 설명이 나오지 않습니다.", "정답: 소스는 ''주소값으로 연결이 이루어져 있는 연결리스트이기 때문에 삽입 삭제가 용이함''이라 직접 설명합니다."], "keywords": ["PCB 관리", "Linked List", "삽입 삭제", "프로세스 생성"], "sourceEvidence": {"section": "Computer Science/Operating System/Process Management & PCB.md", "startLine": 49, "endLine": 53, "quote": "> Linked List 방식으로 관리함\n>\n> PCB List Head에 PCB들이 생성될 때마다 붙게 된다. 주소값으로 연결이 이루어져 있는 연결리스트이기 때문에 삽입 삭제가 용이함.\n>\n> 즉, 프로세스가 생성되면 해당 PCB가 생성되고 프로세스 완료시 제거됨"}, "category": "OPERATING_SYSTEM", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Operating System/Process Management & PCB.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Process%20Management%20%26%20PCB.md", "id": "002a41c3-5351-5d3e-ad0a-fa438d616ada", "review": {"blind": {"slot": 28, "correctOptionText": "삽입과 삭제가 용이하여 프로세스 생성·완료 시 효율적이다", "unambiguous": true, "reason": "문서에서 PCB를 Linked List로 관리하는 이유로 삽입 삭제가 용이함을 설명함.", "position": 4}, "evidenceAudit": {"slot": 28, "passed": true, "reason": "문서는 PCB를 Linked List로 관리하고 ''삽입 삭제가 용이함''을 명시하므로 정답(삽입·삭제 용이)이 문서로 명확히 지지됩니다. 나머지 보기는 문서에 언급되지 않아 오답임이 입증됩니다. 난이도·학습목표·한국어 표현도 적절합니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:7b8eaf5910a19ef43901b1c59b75751bc15c3214a3ad3313c11fd8d8e1d79357"}'::jsonb) ON CONFLICT DO NOTHING;
