INSERT INTO csas.quiz_evidence(quiz_id,ordinal,source_id,document_id,revision,chunk_id,index_version,title,url,locator,evidence_text,category,technology_version) VALUES ('4535488c-89e4-5fbc-826a-deb4a8bbd26f','1','gyoogle','doc:gyoogle:2fbc1051ead9f0a9a1709f1c0e019fb641531ec2bb4b52cf892b3d298fda6fcf','41a7e91356adae7ee598d5ee3c27438449ce55d8','chunk:7c9b51edabbf1526da5221b35755d923f1f3f66cca2ab636a049329dae0a216e','csas-gyoogle-bank-v1','Race Condition','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Race%20Condition.md','Computer Science/Operating System/Race Condition.md#Race Condition이 발생하는 경우','#### Race Condition이 발생하는 경우

1. ##### 커널 작업을 수행하는 중에 인터럽트 발생

   - 문제점 : 커널모드에서 데이터를 로드하여 작업을 수행하다가 인터럽트가 발생하여 같은 데이터를 조작하는 경우
   - 해결법 : 커널모드에서 작업을 수행하는 동안, 인터럽트를 disable 시켜 CPU 제어권을 가져가지 못하도록 한다.

2. ##### 프로세스가 ''System Call''을 하여 커널 모드로 진입하여 작업을 수행하는 도중 문맥 교환이 발생할 때

   - 문제점 : 프로세스1이 커널모드에서 데이터를 조작하는 도중, 시간이 초과되어 CPU 제어권이 프로세스2로 넘어가 같은 데이터를 조작하는 경우 ( 프로세스2가 작업에 반영되지 않음 )
   - 해결법 : 프로세스가 커널모드에서 작업을 하는 경우 시간이 초과되어도 CPU 제어권이 다른 프로세스에게 넘어가지 않도록 함

3. ##### 멀티 프로세서 환경에서 공유 메모리 내의 커널 데이터에 접근할 때

   - 문제점 : 멀티 프로세서 환경에서 2개의 CPU가 동시에 커널 내부의 공유 데이터에 접근하여 조작하는 경우
   - 해결법 : 커널 내부에 있는 각 공유 데이터에 접근할 때마다, 그 데이터에 대한 lock/unlock을 하는 방법','operating-system','') ON CONFLICT DO NOTHING;
INSERT INTO csas.concepts(id,slug,name_ko,name_en,category,description) VALUES ('concept:gyoogle-bb1e8004d89d1c9d','gyoogle-bb1e8004d89d1c9d','Process Address Space','Process Address Space','OPERATING_SYSTEM','gyoogle: Process Address Space') ON CONFLICT DO NOTHING;
INSERT INTO csas.quizzes(id,family_id,version,stem,category,difficulty,origin,status,explanation,source_url,reviewed_at,source_metadata) VALUES ('2dd93539-d1d2-590d-bc39-a2641cae4786','2dd93539-d1d2-590d-bc39-a2641cae4786',1,'운영체제가 같은 프로그램의 코드(Code)를 별도로 관리하여 여러 프로세스에서 공유하게 하는 주된 이유는 무엇입니까?','OPERATING_SYSTEM','MEDIUM','CURATED','READY','문서에는 ''Code는 같은 프로그램 자체에서는 모두 같은 내용이기 때문에 따로 관리하여 공유함''이라고 명시되어 있어, 동일한 내용을 공유함으로써 메모리를 절약하려는 목적임을 알 수 있습니다.

1. 문서에는 코드 공유가 함수 호출 시 스택 할당을 줄이거나 실행 속도를 직접적으로 개선한다고 설명되어 있지 않습니다; 스택과 코드는 별개의 이유로 분리되어 있습니다 (라인 15-19,25-27).
2. 전역 변수는 문서에서 데이터 세그먼트에 저장된다고 설명되어 있으며, 코드 세그먼트와 전역 변수를 함께 두는 이유는 언급되지 않았습니다 (라인 5,8,17).
3. 스택의 LIFO 특성은 스택 세그먼트의 이유로 설명되어 있으며, 코드 공유는 LIFO 특성과 직접적인 관련이 없다고 명시되어 있습니다 (라인 19,25-27).
4. 정답입니다. 문서에서 코드가 동일하므로 따로 관리하여 공유한다고 명시하며 이는 메모리 사용량 절감 목적임을 나타냅니다 (라인 15-18).','https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Process%20Address%20Space.md',now(),'{"slot": 32, "topic": "코드 공유의 목적", "learningObjective": "같은 프로그램의 코드가 별도 관리되어 공유되는 이유와 장점을 비교할 수 있습니다.", "difficulty": "MEDIUM", "question": "운영체제가 같은 프로그램의 코드(Code)를 별도로 관리하여 여러 프로세스에서 공유하게 하는 주된 이유는 무엇입니까?", "options": ["코드를 공유하면 함수 호출 시 스택 할당이 불필요해져 실행 속도가 빨라지기 때문입니다.", "코드 세그먼트에 전역 변수를 함께 두어 접근을 통일하기 위해서입니다.", "코드 공유는 스택의 LIFO 특성을 보장하기 위해 필요합니다.", "동일한 내용이므로 공유하여 메모리 사용량을 줄이기 위해서입니다."], "correctAnswer": 4, "explanation": "문서에는 ''Code는 같은 프로그램 자체에서는 모두 같은 내용이기 때문에 따로 관리하여 공유함''이라고 명시되어 있어, 동일한 내용을 공유함으로써 메모리를 절약하려는 목적임을 알 수 있습니다.", "optionExplanations": ["문서에는 코드 공유가 함수 호출 시 스택 할당을 줄이거나 실행 속도를 직접적으로 개선한다고 설명되어 있지 않습니다; 스택과 코드는 별개의 이유로 분리되어 있습니다 (라인 15-19,25-27).", "전역 변수는 문서에서 데이터 세그먼트에 저장된다고 설명되어 있으며, 코드 세그먼트와 전역 변수를 함께 두는 이유는 언급되지 않았습니다 (라인 5,8,17).", "스택의 LIFO 특성은 스택 세그먼트의 이유로 설명되어 있으며, 코드 공유는 LIFO 특성과 직접적인 관련이 없다고 명시되어 있습니다 (라인 19,25-27).", "정답입니다. 문서에서 코드가 동일하므로 따로 관리하여 공유한다고 명시하며 이는 메모리 사용량 절감 목적임을 나타냅니다 (라인 15-18)."], "keywords": ["코드 공유", "메모리 절약", "코드 세그먼트"], "sourceEvidence": {"section": "Computer Science/Operating System/Process Address Space.md", "startLine": 15, "endLine": 18, "quote": "최대한 데이터를 공유하여 메모리 사용량을 줄여야 합니다. \n\nCode는 같은 프로그램 자체에서는 모두 같은 내용이기 때문에 따로 관리하여 공유함"}, "category": "OPERATING_SYSTEM", "sourceRepository": "gyoogle/tech-interview-for-developer", "sourceCommit": "41a7e91356adae7ee598d5ee3c27438449ce55d8", "sourcePath": "Computer Science/Operating System/Process Address Space.md", "sourceUrl": "https://github.com/gyoogle/tech-interview-for-developer/blob/41a7e91356adae7ee598d5ee3c27438449ce55d8/Computer%20Science/Operating%20System/Process%20Address%20Space.md", "id": "2dd93539-d1d2-590d-bc39-a2641cae4786", "review": {"blind": {"slot": 32, "correctOptionText": "동일한 내용이므로 공유하여 메모리 사용량을 줄이기 위해서입니다.", "unambiguous": true, "reason": "본문에서 코드가 같은 프로그램에서는 모두 같은 내용이므로 따로 관리하여 공유한다고 설명함, 목적은 메모리 절약.", "position": 4}, "evidenceAudit": {"slot": 32, "passed": true, "reason": "원문(라인 15-18)에 ''Code는 ... 같은 내용이기 때문에 따로 관리하여 공유함''이라 적혀 있어 정답(메모리 사용량 절감을 위한 공유)이 정확하며 다른 선택지는 원문 근거와 배치됩니다."}, "humanReview": "NOT_PERFORMED", "model": "gpt-5-mini"}, "dataset": "gyoogle-v1", "sourceDocumentId": "doc:gyoogle:bb1e8004d89d1c9d6b9ecbd036d7b274d17cb09d2e19e65d1614d0013626df58"}'::jsonb) ON CONFLICT DO NOTHING;
