INSERT INTO csas.quiz_options(id,quiz_id,position,text,is_correct) VALUES ('60b221c6-be94-5491-9e92-b378274c9972','f2ce9a64-d227-58f8-b2cb-465d8973ef70',3,'함수의 지역 변수들을 데이터 세그먼트로 옮겨 전역 변수와 함께 공유하여 스택 사용을 없앱니다.',false) ON CONFLICT DO NOTHING;
